create or replace function public.submit_attempt_v2(p_request_id uuid,p_node_id text,p_answers jsonb,p_session_id uuid default null,p_speaking_practised boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();existing private.attempt_requests;result jsonb;payload jsonb:=jsonb_build_object('answers',p_answers,'session',p_session_id,'speaking',p_speaking_practised);
begin
 if u is null or p_request_id is null then raise exception 'Cần đăng nhập và mã lượt nộp.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into existing from private.attempt_requests where user_id=u and request_id=p_request_id;
 if existing.attempt_id is not null then
  if existing.node_id<>p_node_id or existing.payload<>payload then raise exception 'Mã lượt nộp đã được sử dụng cho dữ liệu khác.';end if;
  return(select jsonb_build_object('score',a.score,'attempt_id',a.id,'created_at',a.created_at) from public.attempts a where a.id=existing.attempt_id);
 end if;
 result:=public.submit_attempt(p_node_id,p_answers,p_session_id,p_speaking_practised);
 insert into private.attempt_requests(user_id,request_id,node_id,payload,attempt_id) values(u,p_request_id,p_node_id,payload,(result->>'attempt_id')::uuid);
 return result;
end;$$;
create or replace function public.submit_practice(p_request_id uuid,p_question_ids text[],p_answers jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();old public.practice_attempts;total integer;correct_count integer;score integer;aid uuid;
begin
 if u is null or p_request_id is null then raise exception 'Cần đăng nhập.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into old from public.practice_attempts where user_id=u and request_id=p_request_id;
 if old.id is not null then
  if old.question_ids<>p_question_ids or old.answers<>p_answers then raise exception 'Mã lượt luyện đã được sử dụng cho dữ liệu khác.';end if;
  return jsonb_build_object('score',old.score,'attempt_id',old.id,'created_at',old.created_at);
 end if;
 total:=cardinality(p_question_ids);
 if total is null or total not between 1 and 50 or total<>(select count(distinct x) from unnest(p_question_ids) x) or jsonb_typeof(p_answers)<>'object' or (select count(*) from jsonb_object_keys(p_answers))<>total then raise exception 'Đề luyện hoặc đáp án không hợp lệ.';end if;
 if exists(select 1 from unnest(p_question_ids) q where not p_answers?q or jsonb_typeof(p_answers->q)<>'string' or char_length(p_answers->>q)>500) then raise exception 'Cần trả lời đủ các câu.';end if;
 if exists(select 1 from unnest(p_question_ids) q where not exists(select 1 from public.course_nodes n where n.kind='lesson' and q=any(n.question_ids) and private.unlocked(u,n.id))) then raise exception 'Chỉ luyện câu hỏi trong bài đã mở.';end if;
 if (select count(*) from public.practice_attempts where user_id=u and created_at>now()-interval '1 hour')>=60 then raise exception 'Quá nhiều lượt luyện trong một giờ.';end if;
 select count(*) filter(where private.normalized(p_answers->>k.question_id)=private.normalized(k.answer)) into correct_count from private.answer_keys k where k.question_id=any(p_question_ids);
 if (select count(*) from private.answer_keys where question_id=any(p_question_ids))<>total then raise exception 'Thiếu nội dung chuẩn. Hãy cập nhật SQL v2.0.';end if;
 score:=round(correct_count::numeric/total*100);
 insert into public.practice_attempts(user_id,request_id,question_ids,answers,score) values(u,p_request_id,p_question_ids,p_answers,score) returning id into aid;
 return jsonb_build_object('score',score,'attempt_id',aid,'created_at',now());
end;$$;
create or replace function public.get_practice_history() returns jsonb language sql security definer set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at),'[]') from public.practice_attempts p where p.user_id=auth.uid();$$;
revoke all on function public.submit_attempt_v2(uuid,text,jsonb,uuid,boolean),public.submit_practice(uuid,text[],jsonb),public.get_practice_history() from public,anon;
grant execute on function public.submit_attempt_v2(uuid,text,jsonb,uuid,boolean),public.submit_practice(uuid,text[],jsonb),public.get_practice_history() to authenticated;
create or replace function public.submit_attempt(p_node_id text,p_answers jsonb,p_session_id uuid default null,p_speaking_practised boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();n public.course_nodes;expected text[];qs private.quiz_sessions;num integer;correct_count integer;s integer;aid uuid;feedback jsonb;
begin
 if u is null then raise exception 'Cần đăng nhập.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into n from public.course_nodes where id=p_node_id;
 if n.id is null or not private.unlocked(u,p_node_id) then raise exception 'Bài này chưa được mở khóa.';end if;
 if jsonb_typeof(p_answers)<>'object' then raise exception 'Dữ liệu đáp án không hợp lệ.';end if;
 if n.kind='milestone' then
  select * into qs from private.quiz_sessions where id=p_session_id and user_id=u and node_id=p_node_id for update;
  if qs.id is null or qs.created_at<now()-interval '24 hours' then raise exception 'Phiên kiểm tra không hợp lệ hoặc hết hạn.';end if;
  if qs.attempt_id is not null then
   return(select jsonb_build_object('score',a.score,'attempt_id',a.id) from public.attempts a where a.id=qs.attempt_id);
  end if;
  if not p_speaking_practised then raise exception 'Cần tham gia lượt luyện nói.';end if;
  expected:=qs.question_ids;
 else expected:=n.question_ids;
  if cardinality(n.legacy_question_ids)>0 and (select count(*) from jsonb_object_keys(p_answers))=cardinality(n.legacy_question_ids) and not exists(select 1 from unnest(n.legacy_question_ids) q where not p_answers?q) then expected:=n.legacy_question_ids;end if;
 end if;
 num:=cardinality(expected);
 if num=0 or (select count(*) from jsonb_object_keys(p_answers))<>num or exists(select 1 from unnest(expected) q where not p_answers?q) then raise exception 'Cần trả lời đủ các câu trong đề.';end if;
 if exists(select 1 from unnest(expected) q where jsonb_typeof(p_answers->q)<>'string' or char_length(p_answers->>q)>500) then raise exception 'Đáp án phải là chuỗi văn bản ngắn.';end if;
 if (select count(*) from public.attempts where user_id=u and created_at>now()-interval '1 hour')>=60 then raise exception 'Quá nhiều lượt nộp trong một giờ.';end if;
 select count(*) filter(where private.normalized(p_answers->>k.question_id)=private.normalized(k.answer)),jsonb_agg(jsonb_build_object('id',k.question_id,'correct',private.normalized(p_answers->>k.question_id)=private.normalized(k.answer),'answer',k.answer,'explanation',k.explanation)) into correct_count,feedback from private.answer_keys k where k.question_id=any(expected);
 if (select count(*) from private.answer_keys where question_id=any(expected))<>num then raise exception 'Thiếu đáp án chuẩn. Liên hệ quản trị nội dung.';end if;
 s:=round(correct_count::numeric/num*100);
 insert into public.reviews(user_id,word_id,due) select u,w,now() from unnest(n.word_ids) w on conflict(user_id,word_id) do nothing;
 insert into public.attempts(user_id,node_id,score,answers,speaking_practised) values(u,p_node_id,s,p_answers,case when n.kind='milestone' then p_speaking_practised else false end) returning id into aid;
 if n.kind='milestone' then update private.quiz_sessions set attempt_id=aid where id=qs.id;end if;
 return jsonb_build_object('score',s,'attempt_id',aid,'feedback',feedback);
end;$$;

notify pgrst,'reload schema';

$migration_3$;
 end if;
end $install_3$;

do $install_4$
begin
 if to_regclass('public.writing_attempts') is null then
  execute $migration_4$

create table public.writing_exercises(id text primary key,node_id text not null references public.course_nodes(id),prompt text not null);
create table private.writing_keys(exercise_id text primary key references public.writing_exercises(id),accepted text[] not null);
create table public.writing_attempts(user_id uuid not null references auth.users(id) on delete cascade,request_id uuid not null,exercise_id text not null references public.writing_exercises(id),answer text not null,correct boolean not null,created_at timestamptz not null default now(),primary key(user_id,request_id));
create table public.writing_drafts(user_id uuid not null references auth.users(id) on delete cascade,exercise_id text not null references public.writing_exercises(id),body text not null,revision integer not null default 1,updated_at timestamptz not null default now(),primary key(user_id,exercise_id));
alter table public.writing_exercises enable row level security;
alter table public.writing_attempts enable row level security;
alter table public.writing_drafts enable row level security;
create policy reading_writing_exercises on public.writing_exercises for select to anon,authenticated using(true);
create policy own_writing_attempts on public.writing_attempts for select to authenticated using(user_id=(select auth.uid()));
create policy own_writing_drafts on public.writing_drafts for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.writing_exercises,public.writing_attempts,public.writing_drafts from anon,authenticated;
grant select on public.writing_exercises to anon,authenticated;
grant select on public.writing_attempts,public.writing_drafts to authenticated;
create function private.normalized_writing(s text) returns text language sql immutable set search_path='' as $$
select trim(regexp_replace(regexp_replace(lower(normalize(translate(s,'’‘',$apos$''$apos$),NFKC)),'[.,!?;:“”"]',' ','g'),'\s+',' ','g'));
$$;
create function public.submit_writing(p_request_id uuid,p_exercise_id text,p_answer text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();old public.writing_attempts;node text;correct_answer boolean;
begin
 if u is null or p_request_id is null then raise exception 'Cần đăng nhập.';end if;
 if p_answer is null or char_length(trim(p_answer))=0 or char_length(p_answer)>1000 then raise exception 'Viết từ 1 đến 1000 ký tự.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into old from public.writing_attempts where user_id=u and request_id=p_request_id;
 if old.request_id is not null then
  if old.exercise_id<>p_exercise_id or old.answer<>p_answer then raise exception 'Mã lượt viết đã dùng cho dữ liệu khác.';end if;
  return to_jsonb(old);
 end if;
 select node_id into node from public.writing_exercises where id=p_exercise_id;
 if node is null or not private.unlocked(u,node) then raise exception 'Bài viết chưa mở khóa.';end if;
 if (select count(*) from public.writing_attempts where user_id=u and created_at>now()-interval '1 hour')>=120 then raise exception 'Quá nhiều lượt viết trong một giờ.';end if;
 select exists(select 1 from private.writing_keys k,unnest(k.accepted) a where k.exercise_id=p_exercise_id and private.normalized_writing(a)=private.normalized_writing(p_answer)) into correct_answer;
 insert into public.writing_attempts(user_id,request_id,exercise_id,answer,correct) values(u,p_request_id,p_exercise_id,p_answer,correct_answer) returning * into old;
 return to_jsonb(old);
end;$$;
create function public.save_writing_draft(p_exercise_id text,p_body text,p_revision integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();old public.writing_drafts;node text;
begin
 if u is null then raise exception 'Cần đăng nhập.';end if;
 if p_body is null or char_length(p_body)>1000 or p_revision is null or p_revision<0 then raise exception 'Bản nháp không hợp lệ.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select node_id into node from public.writing_exercises where id=p_exercise_id;
 if node is null or not private.unlocked(u,node) then raise exception 'Bài viết chưa mở khóa.';end if;
 select * into old from public.writing_drafts where user_id=u and exercise_id=p_exercise_id;
 if coalesce(old.revision,0)<>p_revision then raise exception 'Bản nháp tài khoản đã thay đổi trên thiết bị khác.' using errcode='40001';end if;
 insert into public.writing_drafts(user_id,exercise_id,body,revision) values(u,p_exercise_id,p_body,1) on conflict(user_id,exercise_id) do update set body=excluded.body,revision=public.writing_drafts.revision+1,updated_at=now() returning * into old;
 return to_jsonb(old);
end;$$;
revoke all on function public.submit_writing(uuid,text,text),public.save_writing_draft(text,text,integer) from public,anon;
grant execute on function public.submit_writing(uuid,text,text),public.save_writing_draft(text,text,integer) to authenticated;
create function public.admin_seed_writing(p_bundle jsonb) returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Chỉ quản trị viên được nạp nội dung.';end if;
 insert into public.writing_exercises(id,node_id,prompt) select x->>'id',x->>'nodeId',x->>'prompt' from jsonb_array_elements(p_bundle) x on conflict(id) do update set prompt=excluded.prompt,node_id=excluded.node_id;
 insert into private.writing_keys(exercise_id,accepted) select x->>'id',array(select jsonb_array_elements_text(x->'accepted')) from jsonb_array_elements(p_bundle) x on conflict(exercise_id) do update set accepted=excluded.accepted;
end;$$;
revoke all on function public.admin_seed_writing(jsonb) from public,anon,authenticated;
grant execute on function public.admin_seed_writing(jsonb) to service_role;
create or replace function public.app_capabilities() returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('version',2,'offline_attempts',true,'practice',true,'writing',true,'content_version','2.1.0');$$;
notify pgrst,'reload schema';

$migration_4$;
 end if;
end $install_4$;

do $install_5$
begin
 if to_regclass('public.vocabulary_cards') is null then
  execute $migration_5$

create table public.vocabulary_catalog(id text primary key,word text unique not null,meaning text not null,topic text not null,metadata jsonb not null);
create table public.vocabulary_cards(user_id uuid not null references auth.users(id) on delete cascade,word_id text not null references public.vocabulary_catalog(id),saved boolean not null default false,due timestamptz not null default now(),interval integer not null default 0 check(interval>=0),ease numeric not null default 2.5 check(ease between 1.3 and 5),repetitions integer not null default 0 check(repetitions>=0),correct integer not null default 0 check(correct>=0),wrong integer not null default 0 check(wrong>=0),last_reviewed timestamptz,updated_at timestamptz not null default now(),primary key(user_id,word_id));
create table private.vocabulary_events(user_id uuid not null references auth.users(id) on delete cascade,request_id uuid not null,word_id text not null references public.vocabulary_catalog(id),kind text not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(user_id,request_id));
alter table public.vocabulary_catalog enable row level security;
alter table public.vocabulary_cards enable row level security;
create policy read_vocabulary on public.vocabulary_catalog for select to anon,authenticated using(true);
create policy own_vocabulary_cards on public.vocabulary_cards for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.vocabulary_catalog,public.vocabulary_cards from anon,authenticated;
grant select on public.vocabulary_catalog to anon,authenticated;
grant select on public.vocabulary_cards to authenticated;
create function public.admin_seed_vocabulary(p_bundle jsonb) returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Chỉ quản trị viên được nạp từ vựng.';end if;
 insert into public.vocabulary_catalog(id,word,meaning,topic,metadata) select x->>'id',x->>'word',x->>'meaning',x->>'topic',x from jsonb_array_elements(p_bundle) x on conflict(id) do update set word=excluded.word,meaning=excluded.meaning,topic=excluded.topic,metadata=excluded.metadata;
end;$$;
create function public.submit_vocabulary_event(p_request_id uuid,p_word_id text,p_kind text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();e private.vocabulary_events;c public.vocabulary_cards;w public.vocabulary_catalog;q integer;new_interval integer;new_repetitions integer;new_ease numeric;is_correct boolean;result jsonb;
begin
 if u is null or p_request_id is null then raise exception 'Cần đăng nhập.';end if;
 if p_kind is null or p_kind not in ('bookmark','review','answer') or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'Lượt từ vựng không hợp lệ.';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into e from private.vocabulary_events where user_id=u and request_id=p_request_id;
 if e.request_id is not null then
  if e.word_id<>p_word_id or e.kind<>p_kind or e.payload<>p_payload then raise exception 'Mã lượt từ đã dùng cho dữ liệu khác.';end if;
  return e.result;
 end if;
 select * into w from public.vocabulary_catalog where id=p_word_id;
 if w.id is null then raise exception 'Từ này chưa có trong database. Hãy chạy SQL v2.2.';end if;
 if p_kind='bookmark' and (jsonb_typeof(p_payload->'saved') is distinct from 'boolean' or (select count(*) from jsonb_object_keys(p_payload))<>1) then raise exception 'Trạng thái lưu từ không hợp lệ.';end if;
 if p_kind='review' and (jsonb_typeof(p_payload->'quality') is distinct from 'number' or p_payload->>'quality' not in ('1','3','5') or (select count(*) from jsonb_object_keys(p_payload))<>1) then raise exception 'Mức nhớ không hợp lệ.';end if;
 if p_kind='answer' and (p_payload->>'questionKind' is null or p_payload->>'questionKind' not in ('meaning','listening','context') or jsonb_typeof(p_payload->'answer') is distinct from 'string' or char_length(p_payload->>'answer')>500 or (select count(*) from jsonb_object_keys(p_payload))<>2) then raise exception 'Đáp án từ vựng không hợp lệ.';end if;
 if (select count(*) from private.vocabulary_events where user_id=u and created_at>now()-interval '1 hour')>=1200 then raise exception 'Quá nhiều lượt từ trong một giờ.';end if;
 select * into c from public.vocabulary_cards where user_id=u and word_id=w.id;
 if c.word_id is null then
  insert into public.vocabulary_cards(user_id,word_id,due,interval,ease,repetitions) select u,w.id,r.due,r.interval,r.ease,r.repetitions from public.reviews r where r.user_id=u and r.word_id=w.id on conflict do nothing;
  insert into public.vocabulary_cards(user_id,word_id) values(u,w.id) on conflict do nothing;
  select * into c from public.vocabulary_cards where user_id=u and word_id=w.id;
 end if;
 if p_kind='bookmark' then update public.vocabulary_cards set saved=(p_payload->>'saved')::boolean,updated_at=now() where user_id=u and word_id=w.id returning * into c;
 elsif p_kind='review' then
  q:=(p_payload->>'quality')::integer;new_repetitions:=case when q>=3 then c.repetitions+1 else 0 end;
  new_interval:=case when q<3 then 0 when new_repetitions=1 then 1 when new_repetitions=2 then 3 else round(c.interval*c.ease)::integer end;
  new_ease:=least(5,greatest(1.3,c.ease+(0.1-(5-q)*(0.08+(5-q)*0.02))));
  update public.vocabulary_cards set due=now()+case when new_interval=0 then interval '10 minutes' else new_interval*interval '1 day' end,interval=new_interval,ease=new_ease,repetitions=new_repetitions,last_reviewed=now(),updated_at=now() where user_id=u and word_id=w.id returning * into c;
 else
  is_correct:=private.normalized(p_payload->>'answer')=private.normalized(case when p_payload->>'questionKind'='meaning' then w.meaning else w.word end);
  update public.vocabulary_cards set correct=correct+case when is_correct then 1 else 0 end,wrong=wrong+case when is_correct then 0 else 1 end,due=case when is_correct then due else now() end,updated_at=now() where user_id=u and word_id=w.id returning * into c;
 end if;
 result:=jsonb_build_object('card',to_jsonb(c),'correct',is_correct);
 insert into private.vocabulary_events(user_id,request_id,word_id,kind,payload,result) values(u,p_request_id,w.id,p_kind,p_payload,result);
 return result;
end;$$;
create function public.get_vocabulary_state() returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(x),'[]') from (
 select to_jsonb(c) x from public.vocabulary_cards c where user_id=auth.uid()
 union all
 select jsonb_build_object('word_id',r.word_id,'saved',false,'due',r.due,'interval',r.interval,'ease',r.ease,'repetitions',r.repetitions,'correct',0,'wrong',0,'last_reviewed',null) from public.reviews r where user_id=auth.uid() and exists(select 1 from public.vocabulary_catalog w where w.id=r.word_id) and not exists(select 1 from public.vocabulary_cards c where c.user_id=r.user_id and c.word_id=r.word_id)
 ) rows;
$$;
revoke all on function public.admin_seed_vocabulary(jsonb) from public,anon,authenticated;
grant execute on function public.admin_seed_vocabulary(jsonb) to service_role;
revoke all on function public.submit_vocabulary_event(uuid,text,text,jsonb),public.get_vocabulary_state() from public,anon;
grant execute on function public.submit_vocabulary_event(uuid,text,text,jsonb),public.get_vocabulary_state() to authenticated;
create or replace function public.app_capabilities() returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('version',2,'offline_attempts',true,'practice',true,'writing',true,'vocabulary',true,'content_version','2.2.0');$$;
notify pgrst,'reload schema';

$migration_5$;
 end if;
end $install_5$;
