select public.admin_seed_bundle($curriculum${"questions":[{"id":"a0-1-g1","skill":"grammar","prompt":"I ___ a student.","options":["am","is","are"],"answer":"am","explanation":"“I” đi với “am”, không đi với “is” hay “are”."},{"id":"a0-1-g2","skill":"grammar","prompt":"I ___ happy.","options":["am","are","is"],"answer":"am","explanation":"Chủ ngữ là “I”, vì vậy dùng “am”."},{"id":"a0-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am a student.","audio":"/audio/lesson-a0-1.mp3","explanation":"Câu mẫu là: I am a student."},{"id":"first-day-r0","skill":"reading","prompt":"What is Anna?","options":["A student","A teacher","A doctor"],"answer":"A student","explanation":"Anna nói “I am a student”."},{"id":"first-day-r1","skill":"reading","prompt":"What is in her bag?","options":["A book and a pen","A cup and a plate","An apple and milk"],"answer":"A book and a pen","explanation":"Đoạn văn ghi rõ Anna có sách và bút trong cặp."},{"id":"first-day-r2","skill":"reading","prompt":"Who sits next to Anna?","options":["May","Tom","Her father"],"answer":"Tom","explanation":"“My friend Tom sits next to me” cho biết Tom ngồi cạnh Anna."},{"id":"a0-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I am a student.","I is a student.","I are a student."],"answer":"I am a student.","explanation":"“I” đi với “am”, không đi với “is” hay “are”."},{"id":"a0-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I am happy.","I are happy.","I is happy."],"answer":"I am happy.","explanation":"Chủ ngữ là “I”, vì vậy dùng “am”."},{"id":"a0-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I am happy.","audio":"/audio/listen-a0-1-2.mp3","explanation":"Câu nghe được là: I am happy."},{"id":"a0-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I am at home.","audio":"/audio/listen-a0-1-3.mp3","explanation":"Câu nghe được là: I am at home."},{"id":"a0-2-g1","skill":"grammar","prompt":"You ___ my friend.","options":["is","are","am"],"answer":"are","explanation":"“You” đi với “are”, kể cả khi chỉ nói với một người."},{"id":"a0-2-g2","skill":"grammar","prompt":"___ are happy.","options":["I","You","He"],"answer":"You","explanation":"Trong ba chủ ngữ này, chỉ “You” đi với “are”."},{"id":"a0-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"You are my friend.","audio":"/audio/lesson-a0-2.mp3","explanation":"Câu mẫu là: You are my friend."},{"id":"a0-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["You is my friend.","You are my friend.","You am my friend."],"answer":"You are my friend.","explanation":"“You” đi với “are”, kể cả khi chỉ nói với một người."},{"id":"a0-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I are happy.","You are happy.","He are happy."],"answer":"You are happy.","explanation":"Trong ba chủ ngữ này, chỉ “You” đi với “are”."},{"id":"a0-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"You are very kind.","audio":"/audio/listen-a0-2-2.mp3","explanation":"Câu nghe được là: You are very kind."},{"id":"a0-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"You are a student.","audio":"/audio/listen-a0-2-3.mp3","explanation":"Câu nghe được là: You are a student."},{"id":"reader-a0-2-r0","skill":"reading","prompt":"Who is Tom?","options":["A student","A teacher","A driver"],"answer":"A student","explanation":"Tom được giới thiệu là học sinh ngay câu thứ hai."},{"id":"reader-a0-2-r1","skill":"reading","prompt":"What colour is Tom’s pen?","options":["Blue","Red","Black"],"answer":"Blue","explanation":"Bút của Tom màu xanh; bút của người kể màu đỏ. Chú ý đúng người được hỏi."},{"id":"reader-a0-2-r2","skill":"reading","prompt":"What do they do after class?","options":["Walk to the bus","Go swimming","Buy a book"],"answer":"Walk to the bus","explanation":"Sau giờ học, hai bạn đi bộ ra xe buýt, không tiếp tục đọc sách."},{"id":"a0-3-g1","skill":"grammar","prompt":"She ___ a teacher.","options":["are","am","is"],"answer":"is","explanation":"“She” là ngôi thứ ba số ít nên dùng “is”."},{"id":"a0-3-g2","skill":"grammar","prompt":"It ___ a book.","options":["am","is","are"],"answer":"is","explanation":"“It” chỉ một vật và đi với “is”."},{"id":"a0-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She is a teacher.","audio":"/audio/lesson-a0-3.mp3","explanation":"Câu mẫu là: She is a teacher."},{"id":"a0-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She are a teacher.","She am a teacher.","She is a teacher."],"answer":"She is a teacher.","explanation":"“She” là ngôi thứ ba số ít nên dùng “is”."},{"id":"a0-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It am a book.","It is a book.","It are a book."],"answer":"It is a book.","explanation":"“It” chỉ một vật và đi với “is”."},{"id":"a0-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He is my friend.","audio":"/audio/listen-a0-3-2.mp3","explanation":"Câu nghe được là: He is my friend."},{"id":"a0-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"It is a pen.","audio":"/audio/listen-a0-3-3.mp3","explanation":"Câu nghe được là: It is a pen."},{"id":"reader-a0-3-r0","skill":"reading","prompt":"What is the mother?","options":["A teacher","A cook","A student"],"answer":"A teacher","explanation":"Mẹ là giáo viên; bố mới là đầu bếp. Đừng đổi nghề của hai người."},{"id":"reader-a0-3-r1","skill":"reading","prompt":"Where is the father?","options":["In the kitchen","On a bus","At school"],"answer":"In the kitchen","explanation":"Câu “My father is in the kitchen” đặt bố ở trong bếp."},{"id":"reader-a0-3-r2","skill":"reading","prompt":"What colour is the cat?","options":["White","Black","Brown"],"answer":"White","explanation":"“It is white” mô tả con mèo trắng; “it” thay cho “cat”."},{"id":"a0-4-g1","skill":"grammar","prompt":"This is ___ book.","options":["a","an","two"],"answer":"a","explanation":"“Book” bắt đầu bằng âm /b/, nên dùng “a”."},{"id":"a0-4-g2","skill":"grammar","prompt":"It is ___ cat.","options":["an","a","three"],"answer":"a","explanation":"“Cat” bắt đầu bằng âm /k/, nên dùng “a”."},{"id":"a0-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"This is a book.","audio":"/audio/lesson-a0-4.mp3","explanation":"Câu mẫu là: This is a book."},{"id":"a0-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["This is a book.","This is an book.","This is two book."],"answer":"This is a book.","explanation":"“Book” bắt đầu bằng âm /b/, nên dùng “a”."},{"id":"a0-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It is an cat.","It is a cat.","It is three cat."],"answer":"It is a cat.","explanation":"“Cat” bắt đầu bằng âm /k/, nên dùng “a”."},{"id":"a0-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have a cat.","audio":"/audio/listen-a0-4-2.mp3","explanation":"Câu nghe được là: I have a cat."},{"id":"a0-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"This is a cup.","audio":"/audio/listen-a0-4-3.mp3","explanation":"Câu nghe được là: This is a cup."},{"id":"reader-a0-4-r0","skill":"reading","prompt":"Where is the pen?","options":["In the bag","In the cup","Under the chair"],"answer":"In the bag","explanation":"Người kể liệt kê bút cùng sách và cốc trong cặp."},{"id":"reader-a0-4-r1","skill":"reading","prompt":"What colour is the friend’s bag?","options":["Red","Blue","Green"],"answer":"Red","explanation":"Cặp của bạn màu đỏ; quyển sách của người kể mới màu xanh."},{"id":"reader-a0-4-r2","skill":"reading","prompt":"What are they ready for?","options":["Class","Dinner","A holiday"],"answer":"Class","explanation":"Câu cuối nói cả hai đã sẵn sàng vào lớp."},{"id":"a0-5-g1","skill":"grammar","prompt":"It is ___ apple.","options":["a","an","two"],"answer":"an","explanation":"“Apple” bắt đầu bằng âm /æ/, nên dùng “an”."},{"id":"a0-5-g2","skill":"grammar","prompt":"This is ___ orange.","options":["a","an","three"],"answer":"an","explanation":"“Orange” bắt đầu bằng âm nguyên âm, nên dùng “an”."},{"id":"a0-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"It is an apple.","audio":"/audio/lesson-a0-5.mp3","explanation":"Câu mẫu là: It is an apple."},{"id":"a0-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It is a apple.","It is an apple.","It is two apple."],"answer":"It is an apple.","explanation":"“Apple” bắt đầu bằng âm /æ/, nên dùng “an”."},{"id":"a0-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["This is a orange.","This is an orange.","This is three orange."],"answer":"This is an orange.","explanation":"“Orange” bắt đầu bằng âm nguyên âm, nên dùng “an”."},{"id":"a0-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"This is an orange.","audio":"/audio/listen-a0-5-2.mp3","explanation":"Câu nghe được là: This is an orange."},{"id":"a0-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have an apple.","audio":"/audio/listen-a0-5-3.mp3","explanation":"Câu nghe được là: I have an apple."},{"id":"reader-a0-5-r0","skill":"reading","prompt":"What does the sister eat?","options":["An orange","An apple","A banana"],"answer":"An orange","explanation":"Em gái ăn cam; người kể ăn táo. Câu hỏi hỏi về em gái."},{"id":"reader-a0-5-r1","skill":"reading","prompt":"Where are they?","options":["At home","At school","In a shop"],"answer":"At home","explanation":"Câu cuối gọi đây là bữa trưa ở nhà, nên địa điểm là nhà."},{"id":"reader-a0-5-r2","skill":"reading","prompt":"What is on the table?","options":["An apple and an orange","Two books","A bag and a pen"],"answer":"An apple and an orange","explanation":"Hai câu đầu đặt cả táo và cam trên bàn."},{"id":"a0-6-g1","skill":"grammar","prompt":"I have two ___.","options":["book","books","a book"],"answer":"books","explanation":"“Two” là hai, nên danh từ “book” phải thêm “s”."},{"id":"a0-6-g2","skill":"grammar","prompt":"There are three ___.","options":["cat","cats","a cat"],"answer":"cats","explanation":"“Three” là ba, nên dùng danh từ số nhiều “cats”."},{"id":"a0-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have two books.","audio":"/audio/lesson-a0-6.mp3","explanation":"Câu mẫu là: I have two books."},{"id":"a0-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I have two book.","I have two books.","I have two a book."],"answer":"I have two books.","explanation":"“Two” là hai, nên danh từ “book” phải thêm “s”."},{"id":"a0-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["There are three cat.","There are three cats.","There are three a cat."],"answer":"There are three cats.","explanation":"“Three” là ba, nên dùng danh từ số nhiều “cats”."},{"id":"a0-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have three cats.","audio":"/audio/listen-a0-6-2.mp3","explanation":"Câu nghe được là: I have three cats."},{"id":"a0-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"You have two pens.","audio":"/audio/listen-a0-6-3.mp3","explanation":"Câu nghe được là: You have two pens."},{"id":"reader-a0-6-r0","skill":"reading","prompt":"How many cats are there?","options":["Two","Three","One"],"answer":"Two","explanation":"Câu đầu ghi “two cats”, nghĩa là hai con mèo."},{"id":"reader-a0-6-r1","skill":"reading","prompt":"Who puts water on the floor?","options":["The brother","The mother","The teacher"],"answer":"The brother","explanation":"Anh/em trai là người đặt hai cốc nước xuống sàn."},{"id":"reader-a0-6-r2","skill":"reading","prompt":"Where do the cats sit in the morning?","options":["Near the window","On a bus","In a bag"],"answer":"Near the window","explanation":"Vào buổi sáng, hai con mèo ngồi gần cửa sổ."},{"id":"a1-1-g1","skill":"grammar","prompt":"He ___ tea every day.","options":["drink","drinks","drinking"],"answer":"drinks","explanation":"Chủ ngữ là “He”; động từ hiện tại đơn “drink” phải thêm “s”."},{"id":"a1-1-g2","skill":"grammar","prompt":"He ___ books every evening.","options":["reads","read","reading"],"answer":"reads","explanation":"“He” đi với “reads” trong câu hiện tại đơn khẳng định."},{"id":"a1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"He drinks tea.","audio":"/audio/lesson-a1-1.mp3","explanation":"Câu mẫu là: He drinks tea."},{"id":"morning-r0","skill":"reading","prompt":"When does Ben get up?","options":["At seven","At six","At eight"],"answer":"At seven","explanation":"Câu đầu cho biết Ben dậy lúc bảy giờ."},{"id":"morning-r1","skill":"reading","prompt":"Why does he walk to work?","options":["His office is nearby","He has no money","His sister drives"],"answer":"His office is nearby","explanation":"Văn phòng ở gần nhà là lý do Ben đi bộ."},{"id":"morning-r2","skill":"reading","prompt":"What does he do on Saturdays?","options":["Reads at a cafe","Works at his office","Washes his car"],"answer":"Reads at a cafe","explanation":"Anh không đi làm thứ Bảy mà đọc sách ở quán cà phê."},{"id":"a1-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["He drink tea every day.","He drinks tea every day.","He drinking tea every day."],"answer":"He drinks tea every day.","explanation":"Chủ ngữ là “He”; động từ hiện tại đơn “drink” phải thêm “s”."},{"id":"a1-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["He reads books every evening.","He read books every evening.","He reading books every evening."],"answer":"He reads books every evening.","explanation":"“He” đi với “reads” trong câu hiện tại đơn khẳng định."},{"id":"a1-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He reads every evening.","audio":"/audio/listen-a1-1-2.mp3","explanation":"Câu nghe được là: He reads every evening."},{"id":"a1-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He walks to school.","audio":"/audio/listen-a1-1-3.mp3","explanation":"Câu nghe được là: He walks to school."},{"id":"a1-2-g1","skill":"grammar","prompt":"She ___ cups every day.","options":["wash","washs","washes"],"answer":"washes","explanation":"Động từ “wash” kết thúc bằng “sh”, nên thêm “es”."},{"id":"a1-2-g2","skill":"grammar","prompt":"He ___ his car on Sundays.","options":["wash","washes","washs"],"answer":"washes","explanation":"“He” là ngôi thứ ba số ít; “wash” thêm “es” thành “washes”."},{"id":"a1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She washes cups.","audio":"/audio/lesson-a1-2.mp3","explanation":"Câu mẫu là: She washes cups."},{"id":"a1-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She wash cups every day.","She washs cups every day.","She washes cups every day."],"answer":"She washes cups every day.","explanation":"Động từ “wash” kết thúc bằng “sh”, nên thêm “es”."},{"id":"a1-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["He wash his car on Sundays.","He washes his car on Sundays.","He washs his car on Sundays."],"answer":"He washes his car on Sundays.","explanation":"“He” là ngôi thứ ba số ít; “wash” thêm “es” thành “washes”."},{"id":"a1-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He washes his car.","audio":"/audio/listen-a1-2-2.mp3","explanation":"Câu nghe được là: He washes his car."},{"id":"a1-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She washes the plates.","audio":"/audio/listen-a1-2-3.mp3","explanation":"Câu nghe được là: She washes the plates."},{"id":"reader-a1-2-r0","skill":"reading","prompt":"What does Nora wash?","options":["Cups","Cars","Windows"],"answer":"Cups","explanation":"Nora rửa cốc; người anh/em trai lau bàn."},{"id":"reader-a1-2-r1","skill":"reading","prompt":"Why does she like the routine?","options":["Everyone helps","She earns money","She finishes school"],"answer":"Everyone helps","explanation":"Nora thích thói quen này vì mọi người cùng giúp, không ai phải làm một mình."},{"id":"reader-a1-2-r2","skill":"reading","prompt":"What happens after cleaning?","options":["They take a walk","They go to work","They buy a car"],"answer":"They take a walk","explanation":"Sau việc dọn dẹp, gia đình đi bộ một lát."},{"id":"a1-3-g1","skill":"grammar","prompt":"I ___ drink coffee.","options":["don't","doesn't","isn't"],"answer":"don't","explanation":"Với “I”, câu phủ định hiện tại đơn dùng “don't” + động từ nguyên mẫu."},{"id":"a1-3-g2","skill":"grammar","prompt":"I don't ___ coffee.","options":["drinks","drink","drinking"],"answer":"drink","explanation":"Sau “don't”, giữ động từ nguyên mẫu “drink”."},{"id":"a1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I do not drink coffee.","audio":"/audio/lesson-a1-3.mp3","explanation":"Câu mẫu là: I do not drink coffee."},{"id":"a1-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I don't drink coffee.","I doesn't drink coffee.","I isn't drink coffee."],"answer":"I don't drink coffee.","explanation":"Với “I”, câu phủ định hiện tại đơn dùng “don't” + động từ nguyên mẫu."},{"id":"a1-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I don't drinks coffee.","I don't drink coffee.","I don't drinking coffee."],"answer":"I don't drink coffee.","explanation":"Sau “don't”, giữ động từ nguyên mẫu “drink”."},{"id":"a1-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I do not eat meat.","audio":"/audio/listen-a1-3-2.mp3","explanation":"Câu nghe được là: I do not eat meat."},{"id":"a1-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I do not watch television.","audio":"/audio/listen-a1-3-3.mp3","explanation":"Câu nghe được là: I do not watch television."},{"id":"reader-a1-3-r0","skill":"reading","prompt":"What does the narrator prefer to drink?","options":["Water","Coffee","Milk"],"answer":"Water","explanation":"Người kể chọn nước, còn Eva chọn cà phê. Chú ý người được hỏi."},{"id":"reader-a1-3-r1","skill":"reading","prompt":"When do they meet?","options":["On Fridays","Every Sunday","On Mondays"],"answer":"On Fridays","explanation":"Họ gặp ở quán vào các ngày thứ Sáu."},{"id":"reader-a1-3-r2","skill":"reading","prompt":"How long do they talk?","options":["Ten minutes","One hour","Two minutes"],"answer":"Ten minutes","explanation":"Họ nói chuyện mười phút trước khi rời đi."},{"id":"a1-4-g1","skill":"grammar","prompt":"She doesn't ___ milk.","options":["likes","like","liking"],"answer":"like","explanation":"“Doesn't” đã mang dấu hiệu ngôi thứ ba; không thêm “s” vào “like”."},{"id":"a1-4-g2","skill":"grammar","prompt":"He ___ like coffee.","options":["don't","doesn't","isn't"],"answer":"doesn't","explanation":"Với “He”, phủ định hiện tại đơn dùng “doesn't”."},{"id":"a1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She does not like milk.","audio":"/audio/lesson-a1-4.mp3","explanation":"Câu mẫu là: She does not like milk."},{"id":"a1-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She doesn't likes milk.","She doesn't like milk.","She doesn't liking milk."],"answer":"She doesn't like milk.","explanation":"“Doesn't” đã mang dấu hiệu ngôi thứ ba; không thêm “s” vào “like”."},{"id":"a1-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["He don't like coffee.","He doesn't like coffee.","He isn't like coffee."],"answer":"He doesn't like coffee.","explanation":"Với “He”, phủ định hiện tại đơn dùng “doesn't”."},{"id":"a1-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He does not drink tea.","audio":"/audio/listen-a1-4-2.mp3","explanation":"Câu nghe được là: He does not drink tea."},{"id":"a1-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She does not work here.","audio":"/audio/listen-a1-4-3.mp3","explanation":"Câu nghe được là: She does not work here."},{"id":"reader-a1-4-r0","skill":"reading","prompt":"What does the sister do after dinner?","options":["Reads a story","Watches television","Works in a shop"],"answer":"Reads a story","explanation":"Sau bữa tối, chị/em gái đọc một truyện ngắn."},{"id":"reader-a1-4-r1","skill":"reading","prompt":"What does the brother do?","options":["Draws pictures","Reads the same book","Cooks dinner"],"answer":"Draws pictures","explanation":"Anh/em trai không thích đọc nên vẽ tranh thay thế."},{"id":"reader-a1-4-r2","skill":"reading","prompt":"When do they put things away?","options":["At nine","At seven","At midnight"],"answer":"At nine","explanation":"“At nine” là lúc cả hai cất mọi thứ đi."},{"id":"a1-5-g1","skill":"grammar","prompt":"___ you like coffee?","options":["Do","Does","Is"],"answer":"Do","explanation":"Câu hỏi hiện tại đơn với “you” bắt đầu bằng “Do”."},{"id":"a1-5-g2","skill":"grammar","prompt":"Do you ___ tea?","options":["likes","like","liking"],"answer":"like","explanation":"Sau trợ động từ “Do”, động từ giữ nguyên mẫu “like”."},{"id":"a1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Do you like coffee?","audio":"/audio/lesson-a1-5.mp3","explanation":"Câu mẫu là: Do you like coffee?"},{"id":"a1-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Do you like coffee?","Does you like coffee?","Is you like coffee?"],"answer":"Do you like coffee?","explanation":"Câu hỏi hiện tại đơn với “you” bắt đầu bằng “Do”."},{"id":"a1-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Do you likes tea?","Do you like tea?","Do you liking tea?"],"answer":"Do you like tea?","explanation":"Sau trợ động từ “Do”, động từ giữ nguyên mẫu “like”."},{"id":"a1-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Do you read books?","audio":"/audio/listen-a1-5-2.mp3","explanation":"Câu nghe được là: Do you read books?"},{"id":"a1-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Do you walk to school?","audio":"/audio/listen-a1-5-3.mp3","explanation":"Câu nghe được là: Do you walk to school?"},{"id":"reader-a1-5-r0","skill":"reading","prompt":"What is the narrator’s usual hobby?","options":["Drawing","Swimming","Singing"],"answer":"Drawing","explanation":"Người kể nói “I like drawing”, nên sở thích thường ngày là vẽ."},{"id":"reader-a1-5-r1","skill":"reading","prompt":"When will they cook together?","options":["On Saturday","On Monday","Tonight"],"answer":"On Saturday","explanation":"Leo mời người kể nấu ăn cùng gia đình vào thứ Bảy."},{"id":"reader-a1-5-r2","skill":"reading","prompt":"Who invites the narrator?","options":["Leo","The teacher","A shop worker"],"answer":"Leo","explanation":"Leo là người đưa ra lời mời, không phải giáo viên."},{"id":"a1-6-g1","skill":"grammar","prompt":"She can ___.","options":["swims","swim","swimming"],"answer":"swim","explanation":"Sau “can”, dùng “swim”, không thêm “s” hoặc “ing”."},{"id":"a1-6-g2","skill":"grammar","prompt":"He ___ swim well.","options":["can","is","does"],"answer":"can","explanation":"“Can” đứng trực tiếp trước động từ nguyên mẫu để diễn đạt khả năng."},{"id":"a1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I can swim.","audio":"/audio/lesson-a1-6.mp3","explanation":"Câu mẫu là: I can swim."},{"id":"a1-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She can swims.","She can swim.","She can swimming."],"answer":"She can swim.","explanation":"Sau “can”, dùng “swim”, không thêm “s” hoặc “ing”."},{"id":"a1-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["He can swim well.","He is swim well.","He does swim well."],"answer":"He can swim well.","explanation":"“Can” đứng trực tiếp trước động từ nguyên mẫu để diễn đạt khả năng."},{"id":"a1-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She can speak English.","audio":"/audio/listen-a1-6-2.mp3","explanation":"Câu nghe được là: She can speak English."},{"id":"a1-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We can cook rice.","audio":"/audio/listen-a1-6-3.mp3","explanation":"Câu nghe được là: We can cook rice."},{"id":"reader-a1-6-r0","skill":"reading","prompt":"Who helps with the oven?","options":["The teacher","A driver","Nobody"],"answer":"The teacher","explanation":"Giáo viên giúp dùng lò vì các bạn không được dùng một mình."},{"id":"reader-a1-6-r1","skill":"reading","prompt":"What can the narrator do?","options":["Wash vegetables","Use the oven alone","Drive a car"],"answer":"Wash vegetables","explanation":"Người kể rửa rau; người bạn mới là người cắt bánh mì."},{"id":"reader-a1-6-r2","skill":"reading","prompt":"What do they do after sharing the food?","options":["Clean the room","Leave the mess","Buy an oven"],"answer":"Clean the room","explanation":"Sau khi chia sẻ thức ăn, các bạn cùng dọn phòng."},{"id":"a2-1-g1","skill":"grammar","prompt":"I am ___ now.","options":["read","reads","reading"],"answer":"reading","explanation":"Cấu trúc hiện tại tiếp diễn là “am” + động từ đuôi “ing”."},{"id":"a2-1-g2","skill":"grammar","prompt":"I ___ reading right now.","options":["am","is","are"],"answer":"am","explanation":"“I” đi với “am” trong hiện tại tiếp diễn."},{"id":"a2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am reading now.","audio":"/audio/lesson-a2-1.mp3","explanation":"Câu mẫu là: I am reading now."},{"id":"weekend-r0","skill":"reading","prompt":"Where did Mia go?","options":["To a park","To a station","To a museum"],"answer":"To a park","explanation":"Câu đầu nói Mia đến công viên."},{"id":"weekend-r1","skill":"reading","prompt":"Who helped the dog?","options":["A shelter worker","A taxi driver","A teacher"],"answer":"A shelter worker","explanation":"Mia gọi nơi cứu hộ và nhân viên đến giúp."},{"id":"weekend-r2","skill":"reading","prompt":"What will Mia take next time?","options":["A warm coat","A collar","A new phone"],"answer":"A warm coat","explanation":"Câu cuối nói cô định mang áo ấm lần sau."},{"id":"a2-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I am read now.","I am reads now.","I am reading now."],"answer":"I am reading now.","explanation":"Cấu trúc hiện tại tiếp diễn là “am” + động từ đuôi “ing”."},{"id":"a2-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I am reading right now.","I is reading right now.","I are reading right now."],"answer":"I am reading right now.","explanation":"“I” đi với “am” trong hiện tại tiếp diễn."},{"id":"a2-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I am cooking dinner.","audio":"/audio/listen-a2-1-2.mp3","explanation":"Câu nghe được là: I am cooking dinner."},{"id":"a2-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I am waiting outside.","audio":"/audio/listen-a2-1-3.mp3","explanation":"Câu nghe được là: I am waiting outside."},{"id":"a2-2-g1","skill":"grammar","prompt":"We ___ home yesterday.","options":["walk","walked","walking"],"answer":"walked","explanation":"“Yesterday” chỉ quá khứ; “walk” thêm “ed” thành “walked”."},{"id":"a2-2-g2","skill":"grammar","prompt":"She ___ the room last night.","options":["clean","cleans","cleaned"],"answer":"cleaned","explanation":"“Last night” là thời gian quá khứ đã kết thúc; dùng “cleaned”."},{"id":"a2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"We walked home yesterday.","audio":"/audio/lesson-a2-2.mp3","explanation":"Câu mẫu là: We walked home yesterday."},{"id":"a2-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["We walk home yesterday.","We walked home yesterday.","We walking home yesterday."],"answer":"We walked home yesterday.","explanation":"“Yesterday” chỉ quá khứ; “walk” thêm “ed” thành “walked”."},{"id":"a2-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She clean the room last night.","She cleans the room last night.","She cleaned the room last night."],"answer":"She cleaned the room last night.","explanation":"“Last night” là thời gian quá khứ đã kết thúc; dùng “cleaned”."},{"id":"a2-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"They visited us yesterday.","audio":"/audio/listen-a2-2-2.mp3","explanation":"Câu nghe được là: They visited us yesterday."},{"id":"a2-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She cleaned the kitchen.","audio":"/audio/listen-a2-2-3.mp3","explanation":"Câu nghe được là: She cleaned the kitchen."},{"id":"reader-a2-2-r0","skill":"reading","prompt":"Why did they visit the library?","options":["To study","To buy tickets","To meet a doctor"],"answer":"To study","explanation":"Họ muốn nơi yên tĩnh để học, đó là mục đích đến thư viện."},{"id":"reader-a2-2-r1","skill":"reading","prompt":"Who found a room for them?","options":["A librarian","Their teacher","A tourist"],"answer":"A librarian","explanation":"Nhân viên thư viện chỉ cho họ căn phòng nhỏ trên tầng."},{"id":"reader-a2-2-r2","skill":"reading","prompt":"What did the narrator borrow?","options":["An animal book","A travel guide","A newspaper"],"answer":"An animal book","explanation":"Người kể mượn sách về động vật; người anh/em họ chọn sách du lịch."},{"id":"a2-3-g1","skill":"grammar","prompt":"We ___ to the park yesterday.","options":["go","went","goed"],"answer":"went","explanation":"“Go” là động từ bất quy tắc; quá khứ là “went”, không phải “goed”."},{"id":"a2-3-g2","skill":"grammar","prompt":"Yesterday, she ___ home early.","options":["goes","went","going"],"answer":"went","explanation":"“Yesterday” yêu cầu quá khứ; chọn “went”."},{"id":"a2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"We went to the park.","audio":"/audio/lesson-a2-3.mp3","explanation":"Câu mẫu là: We went to the park."},{"id":"a2-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["We go to the park yesterday.","We went to the park yesterday.","We goed to the park yesterday."],"answer":"We went to the park yesterday.","explanation":"“Go” là động từ bất quy tắc; quá khứ là “went”, không phải “goed”."},{"id":"a2-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Yesterday, she goes home early.","Yesterday, she went home early.","Yesterday, she going home early."],"answer":"Yesterday, she went home early.","explanation":"“Yesterday” yêu cầu quá khứ; chọn “went”."},{"id":"a2-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He went home early.","audio":"/audio/listen-a2-3-2.mp3","explanation":"Câu nghe được là: He went home early."},{"id":"a2-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"They went by train.","audio":"/audio/listen-a2-3-3.mp3","explanation":"Câu nghe được là: They went by train."},{"id":"reader-a2-3-r0","skill":"reading","prompt":"How did the family travel?","options":["By train","By car","By plane"],"answer":"By train","explanation":"Câu đầu nói gia đình đi tàu đến bờ biển."},{"id":"reader-a2-3-r1","skill":"reading","prompt":"When did they arrive?","options":["Before lunch","At midnight","After dinner"],"answer":"Before lunch","explanation":"Họ rời nhà sớm và đến nơi trước bữa trưa."},{"id":"reader-a2-3-r2","skill":"reading","prompt":"Where was their hotel?","options":["Near the beach","Inside the station","Far from town"],"answer":"Near the beach","explanation":"Khách sạn nhỏ nằm gần bãi biển, không phải gần ga."},{"id":"a2-4-g1","skill":"grammar","prompt":"Did you ___ London last year?","options":["visit","visited","visits"],"answer":"visit","explanation":"“Did” đã biểu thị quá khứ, nên dùng nguyên mẫu “visit”."},{"id":"a2-4-g2","skill":"grammar","prompt":"___ you visit London last year?","options":["Do","Did","Are"],"answer":"Did","explanation":"“Last year” chỉ quá khứ, nên hỏi bằng “Did”."},{"id":"a2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Did you visit London?","audio":"/audio/lesson-a2-4.mp3","explanation":"Câu mẫu là: Did you visit London?"},{"id":"a2-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Did you visit London last year?","Did you visited London last year?","Did you visits London last year?"],"answer":"Did you visit London last year?","explanation":"“Did” đã biểu thị quá khứ, nên dùng nguyên mẫu “visit”."},{"id":"a2-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Do you visit London last year?","Did you visit London last year?","Are you visit London last year?"],"answer":"Did you visit London last year?","explanation":"“Last year” chỉ quá khứ, nên hỏi bằng “Did”."},{"id":"a2-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Did you call your sister?","audio":"/audio/listen-a2-4-2.mp3","explanation":"Câu nghe được là: Did you call your sister?"},{"id":"a2-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Did they walk home?","audio":"/audio/listen-a2-4-3.mp3","explanation":"Câu nghe được là: Did they walk home?"},{"id":"reader-a2-4-r0","skill":"reading","prompt":"Whom did the narrator visit?","options":["A grandmother","A cousin","A teacher"],"answer":"A grandmother","explanation":"Người kể kể về chuyến thăm bà của mình."},{"id":"reader-a2-4-r1","skill":"reading","prompt":"How many nights did the narrator stay?","options":["Two","Five","One"],"answer":"Two","explanation":"Họ ở lại hai đêm, theo câu “We stayed for two nights”."},{"id":"reader-a2-4-r2","skill":"reading","prompt":"Where did the friend go?","options":["To a museum","To the garden","To the seaside"],"answer":"To a museum","explanation":"Người bạn đi bảo tàng; người kể mới đi thăm bà."},{"id":"a2-5-g1","skill":"grammar","prompt":"Sam is ___ than Tom.","options":["tall","taller","tallest"],"answer":"taller","explanation":"So sánh hai người với “than” dùng “taller”."},{"id":"a2-5-g2","skill":"grammar","prompt":"This bag is ___ than that bag.","options":["small","smaller","smallest"],"answer":"smaller","explanation":"“Small” là tính từ ngắn; so sánh hơn là “smaller”."},{"id":"a2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Sam is taller than Tom.","audio":"/audio/lesson-a2-5.mp3","explanation":"Câu mẫu là: Sam is taller than Tom."},{"id":"a2-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Sam is tall than Tom.","Sam is taller than Tom.","Sam is tallest than Tom."],"answer":"Sam is taller than Tom.","explanation":"So sánh hai người với “than” dùng “taller”."},{"id":"a2-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["This bag is small than that bag.","This bag is smaller than that bag.","This bag is smallest than that bag."],"answer":"This bag is smaller than that bag.","explanation":"“Small” là tính từ ngắn; so sánh hơn là “smaller”."},{"id":"a2-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"This room is smaller.","audio":"/audio/listen-a2-5-2.mp3","explanation":"Câu nghe được là: This room is smaller."},{"id":"a2-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"My bag is lighter.","audio":"/audio/listen-a2-5-3.mp3","explanation":"Câu nghe được là: My bag is lighter."},{"id":"reader-a2-5-r0","skill":"reading","prompt":"Which room was bigger?","options":["The first","The second","Both were equal"],"answer":"The first","explanation":"Phòng thứ nhất lớn hơn nhưng ồn hơn. Câu hỏi chỉ hỏi kích thước."},{"id":"reader-a2-5-r1","skill":"reading","prompt":"Why did they choose the second room?","options":["It was quieter","It was nearer the road","It was bigger"],"answer":"It was quieter","explanation":"Họ chọn phòng thứ hai vì yên tĩnh hơn, thuận tiện đọc và nói chuyện."},{"id":"reader-a2-5-r2","skill":"reading","prompt":"What was brighter in the second room?","options":["The lights","The road","The walls outside"],"answer":"The lights","explanation":"Phòng thứ hai có đèn sáng hơn; kích thước phòng lại nhỏ hơn."},{"id":"a2-6-g1","skill":"grammar","prompt":"I am going to ___ tomorrow.","options":["travel","travels","travelled"],"answer":"travel","explanation":"Sau “going to”, dùng động từ nguyên mẫu “travel”."},{"id":"a2-6-g2","skill":"grammar","prompt":"She ___ going to travel next week.","options":["am","is","are"],"answer":"is","explanation":"Chủ ngữ “She” đi với “is” trong cấu trúc “be going to”."},{"id":"a2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am going to travel.","audio":"/audio/lesson-a2-6.mp3","explanation":"Câu mẫu là: I am going to travel."},{"id":"a2-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I am going to travel tomorrow.","I am going to travels tomorrow.","I am going to travelled tomorrow."],"answer":"I am going to travel tomorrow.","explanation":"Sau “going to”, dùng động từ nguyên mẫu “travel”."},{"id":"a2-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She am going to travel next week.","She is going to travel next week.","She are going to travel next week."],"answer":"She is going to travel next week.","explanation":"Chủ ngữ “She” đi với “is” trong cấu trúc “be going to”."},{"id":"a2-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She is going to cook.","audio":"/audio/listen-a2-6-2.mp3","explanation":"Câu nghe được là: She is going to cook."},{"id":"a2-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We are going to leave.","audio":"/audio/listen-a2-6-3.mp3","explanation":"Câu nghe được là: We are going to leave."},{"id":"reader-a2-6-r0","skill":"reading","prompt":"When will they meet?","options":["At eight","At noon","At six"],"answer":"At eight","explanation":"Cả lớp định gặp ở cổng lúc tám giờ."},{"id":"reader-a2-6-r1","skill":"reading","prompt":"Who will bring gloves?","options":["The teacher","The narrator","A park visitor"],"answer":"The teacher","explanation":"Giáo viên sẽ mang găng tay và túi; người kể mang nước và mũ."},{"id":"reader-a2-6-r2","skill":"reading","prompt":"Why will the narrator take a hat?","options":["It may be sunny","It may snow","The teacher sells hats"],"answer":"It may be sunny","explanation":"Người kể mang mũ vì trời có thể nắng, theo mệnh đề “because”."},{"id":"b1-1-g1","skill":"grammar","prompt":"I have ___ London twice.","options":["visit","visited","visiting"],"answer":"visited","explanation":"Sau “have” trong hiện tại hoàn thành cần quá khứ phân từ “visited”."},{"id":"b1-1-g2","skill":"grammar","prompt":"I ___ visited London twice.","options":["have","am","did"],"answer":"have","explanation":"Trải nghiệm không nêu mốc quá khứ đã kết thúc: dùng “have visited”."},{"id":"b1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have visited London.","audio":"/audio/lesson-b1-1.mp3","explanation":"Câu mẫu là: I have visited London."},{"id":"garden-r0","skill":"reading","prompt":"How long has Leo lived there?","options":["Three years","Since childhood","One month"],"answer":"Three years","explanation":"“For three years” là khoảng thời gian Leo đã sống ở đó."},{"id":"garden-r1","skill":"reading","prompt":"Where will they meet if it rains?","options":["In the library","In the garden","At his house"],"answer":"In the library","explanation":"Mệnh đề kết quả cho biết họ sẽ gặp trong thư viện."},{"id":"garden-r2","skill":"reading","prompt":"What does Leo hope to achieve?","options":["Connect neighbours","Sell the library","Avoid outdoor work"],"answer":"Connect neighbours","explanation":"“Bring more people together” là kết nối mọi người."},{"id":"b1-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I have visit London twice.","I have visited London twice.","I have visiting London twice."],"answer":"I have visited London twice.","explanation":"Sau “have” trong hiện tại hoàn thành cần quá khứ phân từ “visited”."},{"id":"b1-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I have visited London twice.","I am visited London twice.","I did visited London twice."],"answer":"I have visited London twice.","explanation":"Trải nghiệm không nêu mốc quá khứ đã kết thúc: dùng “have visited”."},{"id":"b1-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have tried this before.","audio":"/audio/listen-b1-1-2.mp3","explanation":"Câu nghe được là: I have tried this before."},{"id":"b1-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have seen that film.","audio":"/audio/listen-b1-1-3.mp3","explanation":"Câu nghe được là: I have seen that film."},{"id":"b1-2-g1","skill":"grammar","prompt":"I have lived here ___ 2020.","options":["for","since","during"],"answer":"since","explanation":"“2020” là mốc bắt đầu, nên dùng “since”."},{"id":"b1-2-g2","skill":"grammar","prompt":"She has worked here ___ Monday.","options":["since","for","during"],"answer":"since","explanation":"“Monday” là mốc thời gian, không phải một khoảng thời lượng."},{"id":"b1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have lived here since 2020.","audio":"/audio/lesson-b1-2.mp3","explanation":"Câu mẫu là: I have lived here since 2020."},{"id":"b1-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I have lived here for 2020.","I have lived here since 2020.","I have lived here during 2020."],"answer":"I have lived here since 2020.","explanation":"“2020” là mốc bắt đầu, nên dùng “since”."},{"id":"b1-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She has worked here since Monday.","She has worked here for Monday.","She has worked here during Monday."],"answer":"She has worked here since Monday.","explanation":"“Monday” là mốc thời gian, không phải một khoảng thời lượng."},{"id":"b1-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She has worked here since Monday.","audio":"/audio/listen-b1-2-2.mp3","explanation":"Câu nghe được là: She has worked here since Monday."},{"id":"b1-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We have known him since childhood.","audio":"/audio/listen-b1-2-3.mp3","explanation":"Câu nghe được là: We have known him since childhood."},{"id":"reader-b1-2-r0","skill":"reading","prompt":"When did the narrator meet Sara?","options":["Last spring","In childhood","Last night"],"answer":"Last spring","explanation":"“Since last spring” cho biết họ đã quen nhau từ mùa xuân năm ngoái."},{"id":"reader-b1-2-r1","skill":"reading","prompt":"What started their closer friendship?","options":["An offer to carry shopping","A cooking competition","A formal meeting"],"answer":"An offer to carry shopping","explanation":"Sara đề nghị giúp xách túi đồ nặng; hành động nhỏ đó mở đầu tình bạn gần gũi hơn."},{"id":"reader-b1-2-r2","skill":"reading","prompt":"Since when has Sara lived there?","options":["2021","Last week","2010"],"answer":"2021","explanation":"Sara đã sống trong tòa nhà từ năm 2021."},{"id":"b1-3-g1","skill":"grammar","prompt":"I have lived here ___ three years.","options":["since","for","at"],"answer":"for","explanation":"“Three years” là khoảng thời lượng, nên dùng “for”."},{"id":"b1-3-g2","skill":"grammar","prompt":"She has waited ___ two hours.","options":["since","for","on"],"answer":"for","explanation":"“Two hours” là khoảng thời gian kéo dài, nên dùng “for”."},{"id":"b1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have lived here for years.","audio":"/audio/lesson-b1-3.mp3","explanation":"Câu mẫu là: I have lived here for years."},{"id":"b1-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I have lived here since three years.","I have lived here for three years.","I have lived here at three years."],"answer":"I have lived here for three years.","explanation":"“Three years” là khoảng thời lượng, nên dùng “for”."},{"id":"b1-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She has waited since two hours.","She has waited for two hours.","She has waited on two hours."],"answer":"She has waited for two hours.","explanation":"“Two hours” là khoảng thời gian kéo dài, nên dùng “for”."},{"id":"b1-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"They have waited for two hours.","audio":"/audio/listen-b1-3-2.mp3","explanation":"Câu nghe được là: They have waited for two hours."},{"id":"b1-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He has studied for three months.","audio":"/audio/listen-b1-3-3.mp3","explanation":"Câu nghe được là: He has studied for three months."},{"id":"reader-b1-3-r0","skill":"reading","prompt":"How long has Ben studied English?","options":["Three months","Three years","One week"],"answer":"Three months","explanation":"Câu đầu nói Ben đã học tiếng Anh ba tháng; “for” giới thiệu khoảng thời gian."},{"id":"reader-b1-3-r1","skill":"reading","prompt":"What does he do on difficult days?","options":["Chooses a shorter exercise","Stops for a month","Takes a long test"],"answer":"Chooses a shorter exercise","explanation":"Vào ngày khó khăn, Ben chọn bài ngắn hơn thay vì bỏ học hoàn toàn."},{"id":"reader-b1-3-r2","skill":"reading","prompt":"What improved with regular practice?","options":["His understanding of conversations","His cooking speed","His handwriting only"],"answer":"His understanding of conversations","explanation":"Ben vẫn mắc lỗi nhưng hiểu được nhiều nội dung hội thoại hơn."},{"id":"b1-4-g1","skill":"grammar","prompt":"If it ___, I will stay home.","options":["rains","will rain","rained"],"answer":"rains","explanation":"Điều kiện có thể xảy ra: sau “if” dùng hiện tại đơn “rains”."},{"id":"b1-4-g2","skill":"grammar","prompt":"If she ___ early, we will leave.","options":["arrives","will arrive","arrived"],"answer":"arrives","explanation":"Mệnh đề “if” của điều kiện loại 1 dùng hiện tại đơn."},{"id":"b1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"If it rains, I will stay.","audio":"/audio/lesson-b1-4.mp3","explanation":"Câu mẫu là: If it rains, I will stay."},{"id":"b1-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["If it rains, I will stay home.","If it will rain, I will stay home.","If it rained, I will stay home."],"answer":"If it rains, I will stay home.","explanation":"Điều kiện có thể xảy ra: sau “if” dùng hiện tại đơn “rains”."},{"id":"b1-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["If she arrives early, we will leave.","If she will arrive early, we will leave.","If she arrived early, we will leave."],"answer":"If she arrives early, we will leave.","explanation":"Mệnh đề “if” của điều kiện loại 1 dùng hiện tại đơn."},{"id":"b1-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"If you practise, you will improve.","audio":"/audio/listen-b1-4-2.mp3","explanation":"Câu nghe được là: If you practise, you will improve."},{"id":"b1-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"If she calls, I will answer.","audio":"/audio/listen-b1-4-3.mp3","explanation":"Câu nghe được là: If she calls, I will answer."},{"id":"reader-b1-4-r0","skill":"reading","prompt":"Where will they meet if it rains?","options":["In the community hall","Beside the river","At the station"],"answer":"In the community hall","explanation":"Nếu mưa, buổi dã ngoại chuyển vào hội trường."},{"id":"reader-b1-4-r1","skill":"reading","prompt":"What will everyone bring?","options":["One dish","A new table","Two games"],"answer":"One dish","explanation":"Mỗi người sẽ mang một món ăn; hai tình nguyện viên mới phụ trách trò chơi."},{"id":"reader-b1-4-r2","skill":"reading","prompt":"Whom will the narrator call?","options":["New families","Only the volunteers","A weather reporter"],"answer":"New families","explanation":"Người kể sẽ gọi các gia đình mới để báo địa điểm."},{"id":"b1-5-g1","skill":"grammar","prompt":"The woman ___ called is here.","options":["which","who","where"],"answer":"who","explanation":"Đối tượng được mô tả là người, nên dùng “who”."},{"id":"b1-5-g2","skill":"grammar","prompt":"The teacher ___ helped me is kind.","options":["who","which","where"],"answer":"who","explanation":"“Teacher” chỉ người; đại từ quan hệ phù hợp là “who”."},{"id":"b1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The woman who called is here.","audio":"/audio/lesson-b1-5.mp3","explanation":"Câu mẫu là: The woman who called is here."},{"id":"b1-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["The woman which called is here.","The woman who called is here.","The woman where called is here."],"answer":"The woman who called is here.","explanation":"Đối tượng được mô tả là người, nên dùng “who”."},{"id":"b1-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["The teacher who helped me is kind.","The teacher which helped me is kind.","The teacher where helped me is kind."],"answer":"The teacher who helped me is kind.","explanation":"“Teacher” chỉ người; đại từ quan hệ phù hợp là “who”."},{"id":"b1-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"The man who helped is outside.","audio":"/audio/listen-b1-5-2.mp3","explanation":"Câu nghe được là: The man who helped is outside."},{"id":"b1-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I met a teacher who sings.","audio":"/audio/listen-b1-5-3.mp3","explanation":"Câu nghe được là: I met a teacher who sings."},{"id":"reader-b1-5-r0","skill":"reading","prompt":"Who helped the narrator most?","options":["A colleague","A customer","A driver"],"answer":"A colleague","explanation":"Người đồng nghiệp giải thích công việc rõ ràng và kiên nhẫn, nên giúp người kể nhiều nhất."},{"id":"reader-b1-5-r1","skill":"reading","prompt":"Why was her help important?","options":["The manager was often busy","The job needed no training","The narrator refused questions"],"answer":"The manager was often busy","explanation":"Quản lý thường bận; vì thế sự hỗ trợ của đồng nghiệp đặc biệt quan trọng."},{"id":"reader-b1-5-r2","skill":"reading","prompt":"What does the narrator do now?","options":["Helps a new employee","Leaves the workplace","Avoids beginners"],"answer":"Helps a new employee","explanation":"Hiện người kể cố giúp nhân viên mới với sự kiên nhẫn tương tự."},{"id":"b1-6-g1","skill":"grammar","prompt":"I used to ___ to school.","options":["walked","walk","walking"],"answer":"walk","explanation":"Sau “used to”, dùng động từ nguyên mẫu “walk”."},{"id":"b1-6-g2","skill":"grammar","prompt":"She ___ live in Paris, but now she lives in Rome.","options":["used to","use to","is used to"],"answer":"used to","explanation":"Thói quen hoặc trạng thái trong quá khứ đã thay đổi dùng “used to”."},{"id":"b1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I used to walk to school.","audio":"/audio/lesson-b1-6.mp3","explanation":"Câu mẫu là: I used to walk to school."},{"id":"b1-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I used to walked to school.","I used to walk to school.","I used to walking to school."],"answer":"I used to walk to school.","explanation":"Sau “used to”, dùng động từ nguyên mẫu “walk”."},{"id":"b1-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She used to live in Paris, but now she lives in Rome.","She use to live in Paris, but now she lives in Rome.","She is used to live in Paris, but now she lives in Rome."],"answer":"She used to live in Paris, but now she lives in Rome.","explanation":"Thói quen hoặc trạng thái trong quá khứ đã thay đổi dùng “used to”."},{"id":"b1-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She used to live here.","audio":"/audio/listen-b1-6-2.mp3","explanation":"Câu nghe được là: She used to live here."},{"id":"b1-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We used to travel by bus.","audio":"/audio/listen-b1-6-3.mp3","explanation":"Câu nghe được là: We used to travel by bus."},{"id":"reader-b1-6-r0","skill":"reading","prompt":"What was added last year?","options":["Trees and benches","A railway station","More car parks"],"answer":"Trees and benches","explanation":"Hội đồng thêm cây và ghế dài vào năm ngoái."},{"id":"reader-b1-6-r1","skill":"reading","prompt":"What did the family use to do?","options":["Drive elsewhere for a walk","Meet after school","Work in the shops"],"answer":"Drive elsewhere for a walk","explanation":"Trước đây gia đình lái xe đến nơi khác để đi dạo, thay vì ở khu phố."},{"id":"reader-b1-6-r2","skill":"reading","prompt":"How did the changes affect daily life?","options":["Made it more pleasant","Stopped all shopping","Removed places to sit"],"answer":"Made it more pleasant","explanation":"Những thay đổi đơn giản làm cuộc sống hằng ngày dễ chịu hơn."},{"id":"b2-1-g1","skill":"grammar","prompt":"The report was ___ yesterday.","options":["write","written","writing"],"answer":"written","explanation":"Bị động “was” + quá khứ phân từ của “write” là “written”."},{"id":"b2-1-g2","skill":"grammar","prompt":"The results were ___ yesterday.","options":["announce","announced","announcing"],"answer":"announced","explanation":"Sau “were” trong câu bị động dùng quá khứ phân từ “announced”."},{"id":"b2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The report was written yesterday.","audio":"/audio/lesson-b2-1.mp3","explanation":"Câu mẫu là: The report was written yesterday."},{"id":"research-r0","skill":"reading","prompt":"Why did the researchers advise caution?","options":["The sample was small","The report was lost","No one took part"],"answer":"The sample was small","explanation":"Nhóm thử nghiệm nhỏ khiến kết quả chưa đủ để kết luận rộng."},{"id":"research-r1","skill":"reading","prompt":"What is needed next?","options":["A larger trial","Another newspaper","An apology"],"answer":"A larger trial","explanation":"Trưởng nhóm nói cần một thử nghiệm quy mô lớn hơn."},{"id":"research-r2","skill":"reading","prompt":"How did newspapers present the treatment?","options":["As a breakthrough","As a proven failure","As an old tradition"],"answer":"As a breakthrough","explanation":"Báo chí gọi đó là đột phá dù dữ liệu còn hạn chế."},{"id":"b2-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["The report was write yesterday.","The report was written yesterday.","The report was writing yesterday."],"answer":"The report was written yesterday.","explanation":"Bị động “was” + quá khứ phân từ của “write” là “written”."},{"id":"b2-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["The results were announce yesterday.","The results were announced yesterday.","The results were announcing yesterday."],"answer":"The results were announced yesterday.","explanation":"Sau “were” trong câu bị động dùng quá khứ phân từ “announced”."},{"id":"b2-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"The windows were cleaned today.","audio":"/audio/listen-b2-1-2.mp3","explanation":"Câu nghe được là: The windows were cleaned today."},{"id":"b2-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"The letter was sent yesterday.","audio":"/audio/listen-b2-1-3.mp3","explanation":"Câu nghe được là: The letter was sent yesterday."},{"id":"b2-2-g1","skill":"grammar","prompt":"If I had time, I would ___.","options":["travel","travelled","travels"],"answer":"travel","explanation":"Sau “would”, động từ giữ nguyên mẫu “travel”."},{"id":"b2-2-g2","skill":"grammar","prompt":"If she had money, she ___ travel.","options":["would","will","is"],"answer":"would","explanation":"Giả định không có thật ở hiện tại dùng “would” ở mệnh đề kết quả."},{"id":"b2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I would travel if I could.","audio":"/audio/lesson-b2-2.mp3","explanation":"Câu mẫu là: I would travel if I could."},{"id":"b2-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["If I had time, I would travel.","If I had time, I would travelled.","If I had time, I would travels."],"answer":"If I had time, I would travel.","explanation":"Sau “would”, động từ giữ nguyên mẫu “travel”."},{"id":"b2-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["If she had money, she would travel.","If she had money, she will travel.","If she had money, she is travel."],"answer":"If she had money, she would travel.","explanation":"Giả định không có thật ở hiện tại dùng “would” ở mệnh đề kết quả."},{"id":"b2-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I would help if I could.","audio":"/audio/listen-b2-2-2.mp3","explanation":"Câu nghe được là: I would help if I could."},{"id":"b2-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She would stay if she had time.","audio":"/audio/listen-b2-2-3.mp3","explanation":"Câu nghe được là: She would stay if she had time."},{"id":"reader-b2-2-r0","skill":"reading","prompt":"Why must the narrator choose carefully?","options":["Time is limited","All courses are cancelled","The office has no projects"],"answer":"Time is limited","explanation":"Người kể không đủ thời gian để học mọi khóa nên phải chọn."},{"id":"reader-b2-2-r1","skill":"reading","prompt":"Which course is selected?","options":["One useful for the current project","Every design course","The longest available course"],"answer":"One useful for the current project","explanation":"Người kể chọn một khóa hữu ích cho dự án hiện tại."},{"id":"reader-b2-2-r2","skill":"reading","prompt":"What will the narrator postpone?","options":["Learning design","The current project","All training"],"answer":"Learning design","explanation":"Người kể muốn học thiết kế nhưng quyết định để việc đó sau."},{"id":"b2-3-g1","skill":"grammar","prompt":"___ it rained, we went out.","options":["Despite","Although","In spite of"],"answer":"Although","explanation":"Sau chỗ trống là mệnh đề “it rained”; dùng “Although”."},{"id":"b2-3-g2","skill":"grammar","prompt":"Although ___, we continued.","options":["the rain","it was raining","of the rain"],"answer":"it was raining","explanation":"“Although” đi với mệnh đề đầy đủ “it was raining”."},{"id":"b2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Although it rained, we left.","audio":"/audio/lesson-b2-3.mp3","explanation":"Câu mẫu là: Although it rained, we left."},{"id":"b2-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Despite it rained, we went out.","Although it rained, we went out.","In spite of it rained, we went out."],"answer":"Although it rained, we went out.","explanation":"Sau chỗ trống là mệnh đề “it rained”; dùng “Although”."},{"id":"b2-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Although the rain, we continued.","Although it was raining, we continued.","Although of the rain, we continued."],"answer":"Although it was raining, we continued.","explanation":"“Although” đi với mệnh đề đầy đủ “it was raining”."},{"id":"b2-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Although she was tired, she smiled.","audio":"/audio/listen-b2-3-2.mp3","explanation":"Câu nghe được là: Although she was tired, she smiled."},{"id":"b2-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Although it was late, we continued.","audio":"/audio/listen-b2-3-3.mp3","explanation":"Câu nghe được là: Although it was late, we continued."},{"id":"reader-b2-3-r0","skill":"reading","prompt":"Why did the meeting continue?","options":["Important decisions were unresolved","The chairs were missing","Everyone wanted a longer discussion"],"answer":"Important decisions were unresolved","explanation":"Hai quyết định quan trọng chưa được giải quyết và hạn chót đang đến, nên họ tiếp tục họp."},{"id":"reader-b2-3-r1","skill":"reading","prompt":"How did the chair help?","options":["Summarised the options","Repeated everything","Cancelled the deadline"],"answer":"Summarised the options","explanation":"Người chủ trì tóm tắt các lựa chọn, giúp nhóm tập trung."},{"id":"reader-b2-3-r2","skill":"reading","prompt":"Did everyone prefer the same solution?","options":["No","Yes","The text does not mention preferences"],"answer":"No","explanation":"Đoạn văn nói không phải ai cũng thích cùng một giải pháp; thống nhất bước tiếp theo vẫn có thể đạt được."},{"id":"b2-4-g1","skill":"grammar","prompt":"___ the rain, we went out.","options":["Although","Despite","Even though"],"answer":"Despite","explanation":"“The rain” là cụm danh từ, nên dùng “Despite”."},{"id":"b2-4-g2","skill":"grammar","prompt":"Despite ___, we continued.","options":["it rained","the rain","that it rains"],"answer":"the rain","explanation":"“Despite” đứng trước cụm danh từ “the rain”."},{"id":"b2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Despite the rain, we left.","audio":"/audio/lesson-b2-4.mp3","explanation":"Câu mẫu là: Despite the rain, we left."},{"id":"b2-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Although the rain, we went out.","Despite the rain, we went out.","Even though the rain, we went out."],"answer":"Despite the rain, we went out.","explanation":"“The rain” là cụm danh từ, nên dùng “Despite”."},{"id":"b2-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Despite it rained, we continued.","Despite the rain, we continued.","Despite that it rains, we continued."],"answer":"Despite the rain, we continued.","explanation":"“Despite” đứng trước cụm danh từ “the rain”."},{"id":"b2-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Despite the noise, he slept.","audio":"/audio/listen-b2-4-2.mp3","explanation":"Câu nghe được là: Despite the noise, he slept."},{"id":"b2-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Despite the delay, we arrived on time.","audio":"/audio/listen-b2-4-3.mp3","explanation":"Câu nghe được là: Despite the delay, we arrived on time."},{"id":"reader-b2-4-r0","skill":"reading","prompt":"Did the exhibition open on time?","options":["Yes","No","It was cancelled"],"answer":"Yes","explanation":"Triển lãm vẫn mở đúng giờ dù hàng giao chậm. “Despite” nêu trở ngại, không đổi kết quả."},{"id":"reader-b2-4-r1","skill":"reading","prompt":"What did visitors appreciate?","options":["Clear information","Hidden problems","A longer delivery delay"],"answer":"Clear information","explanation":"Khách đánh giá cao thông tin rõ ràng về khu vực mở muộn."},{"id":"reader-b2-4-r2","skill":"reading","prompt":"How did the organisers respond?","options":["Explained the problem honestly","Pretended nothing was wrong","Refused all visitors"],"answer":"Explained the problem honestly","explanation":"Ban tổ chức giải thích vấn đề trung thực thay vì giả vờ mọi thứ ổn."},{"id":"b2-5-g1","skill":"grammar","prompt":"She must have ___ the time.","options":["forget","forgot","forgotten"],"answer":"forgotten","explanation":"Sau “must have” cần quá khứ phân từ “forgotten”."},{"id":"b2-5-g2","skill":"grammar","prompt":"The floor is wet. It ___ rained overnight.","options":["must have","must","has to"],"answer":"must have","explanation":"Suy luận về một việc trong quá khứ dùng “must have” + V3."},{"id":"b2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She must have forgotten.","audio":"/audio/lesson-b2-5.mp3","explanation":"Câu mẫu là: She must have forgotten."},{"id":"b2-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She must have forget the time.","She must have forgot the time.","She must have forgotten the time."],"answer":"She must have forgotten the time.","explanation":"Sau “must have” cần quá khứ phân từ “forgotten”."},{"id":"b2-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["The floor is wet. It must have rained overnight.","The floor is wet. It must rained overnight.","The floor is wet. It has to rained overnight."],"answer":"The floor is wet. It must have rained overnight.","explanation":"Suy luận về một việc trong quá khứ dùng “must have” + V3."},{"id":"b2-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He must have missed the train.","audio":"/audio/listen-b2-5-2.mp3","explanation":"Câu nghe được là: He must have missed the train."},{"id":"b2-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"They must have heard the news.","audio":"/audio/listen-b2-5-3.mp3","explanation":"Câu nghe được là: They must have heard the news."},{"id":"reader-b2-5-r0","skill":"reading","prompt":"What did the brother suggest?","options":["She had taken the earlier train","She had bought a car","She was at home cooking"],"answer":"She had taken the earlier train","explanation":"Người anh/em suy luận cô bạn hẳn đã lên chuyến tàu trước."},{"id":"reader-b2-5-r1","skill":"reading","prompt":"Why was the narrator less certain?","options":["She normally sent a message","The station was closed","No train had left"],"answer":"She normally sent a message","explanation":"Người kể chưa chắc vì cô bạn thường nhắn tin trước khi đổi kế hoạch."},{"id":"reader-b2-5-r2","skill":"reading","prompt":"What did they check next?","options":["The ticket office","A restaurant","Their school"],"answer":"The ticket office","explanation":"Họ quyết định kiểm tra quầy vé để tìm thêm bằng chứng."},{"id":"b2-6-g1","skill":"grammar","prompt":"They had ___ before I arrived.","options":["leave","left","leaving"],"answer":"left","explanation":"Hành động rời đi xảy ra trước việc đến; dùng “had left”."},{"id":"b2-6-g2","skill":"grammar","prompt":"When I arrived, they ___ already left.","options":["have","had","are"],"answer":"had","explanation":"Hai mốc đều trong quá khứ; hành động trước dùng “had”."},{"id":"b2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"They had left before I arrived.","audio":"/audio/lesson-b2-6.mp3","explanation":"Câu mẫu là: They had left before I arrived."},{"id":"b2-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["They had leave before I arrived.","They had left before I arrived.","They had leaving before I arrived."],"answer":"They had left before I arrived.","explanation":"Hành động rời đi xảy ra trước việc đến; dùng “had left”."},{"id":"b2-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["When I arrived, they have already left.","When I arrived, they had already left.","When I arrived, they are already left."],"answer":"When I arrived, they had already left.","explanation":"Hai mốc đều trong quá khứ; hành động trước dùng “had”."},{"id":"b2-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"She had finished before we arrived.","audio":"/audio/listen-b2-6-2.mp3","explanation":"Câu nghe được là: She had finished before we arrived."},{"id":"b2-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We had eaten before they called.","audio":"/audio/listen-b2-6-3.mp3","explanation":"Câu nghe được là: We had eaten before they called."},{"id":"reader-b2-6-r0","skill":"reading","prompt":"What had the team tested earlier?","options":["A spare microphone","A new restaurant","The guests’ phones"],"answer":"A spare microphone","explanation":"Đội đã thử một micro dự phòng trước sự kiện."},{"id":"reader-b2-6-r1","skill":"reading","prompt":"Why was a short guide printed?","options":["To help anyone who missed part","To replace all chairs","To sell equipment"],"answer":"To help anyone who missed part","explanation":"Bản hướng dẫn dành cho người bỏ lỡ một phần bài thuyết trình."},{"id":"reader-b2-6-r2","skill":"reading","prompt":"What did preparation achieve?","options":["A quick response to a problem","A guarantee of no problems","A shorter audience list"],"answer":"A quick response to a problem","explanation":"Chuẩn bị không loại hết sự cố, nhưng giúp đổi micro nhanh và giữ sự chú ý của khán giả."},{"id":"c1-1-g1","skill":"grammar","prompt":"Never ___ I seen such care.","options":["have","I have","having"],"answer":"have","explanation":"“Never” đầu câu yêu cầu đảo trợ động từ: “Never have I…”."},{"id":"c1-1-g2","skill":"grammar","prompt":"Never ___ such a moving speech.","options":["I have heard","have I heard","I heard have"],"answer":"have I heard","explanation":"Cấu trúc đúng là “Never + have + I + heard”."},{"id":"c1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Never have I seen such care.","audio":"/audio/lesson-c1-1.mp3","explanation":"Câu mẫu là: Never have I seen such care."},{"id":"museum-r0","skill":"reading","prompt":"What concerned the curator most?","options":["A lack of perspective","The price of tickets","The lighting"],"answer":"A lack of perspective","explanation":"Câu chẻ nhấn mạnh sự thiếu góc nhìn là mối lo chính."},{"id":"museum-r1","skill":"reading","prompt":"Whom would she invite?","options":["Community members","Only the manager","No one"],"answer":"Community members","explanation":"Cô muốn mời thành viên cộng đồng đóng góp."},{"id":"museum-r2","skill":"reading","prompt":"How did the team respond?","options":["Enthusiastically","With indifference","By cancelling the exhibition"],"answer":"Enthusiastically","explanation":"Câu cuối mô tả sự hào hứng chưa từng thấy."},{"id":"c1-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Never have I seen such care.","Never I have I seen such care.","Never having I seen such care."],"answer":"Never have I seen such care.","explanation":"“Never” đầu câu yêu cầu đảo trợ động từ: “Never have I…”."},{"id":"c1-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Never I have heard such a moving speech.","Never have I heard such a moving speech.","Never I heard have such a moving speech."],"answer":"Never have I heard such a moving speech.","explanation":"Cấu trúc đúng là “Never + have + I + heard”."},{"id":"c1-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Never had I felt so welcome.","audio":"/audio/listen-c1-1-2.mp3","explanation":"Câu nghe được là: Never had I felt so welcome."},{"id":"c1-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Never have they worked so carefully.","audio":"/audio/listen-c1-1-3.mp3","explanation":"Câu nghe được là: Never have they worked so carefully."},{"id":"c1-2-g1","skill":"grammar","prompt":"Not only ___ she help, but she also stayed.","options":["did","she did","does she"],"answer":"did","explanation":"Quá khứ đơn với “Not only” đầu câu: “did + she + help”."},{"id":"c1-2-g2","skill":"grammar","prompt":"Not only did he ___, but he also apologised.","options":["listen","listened","listening"],"answer":"listen","explanation":"Sau trợ động từ “did”, dùng động từ nguyên mẫu “listen”."},{"id":"c1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Not only did she help, she stayed.","audio":"/audio/lesson-c1-2.mp3","explanation":"Câu mẫu là: Not only did she help, she stayed."},{"id":"c1-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Not only did she help, but she also stayed.","Not only she did she help, but she also stayed.","Not only does she she help, but she also stayed."],"answer":"Not only did she help, but she also stayed.","explanation":"Quá khứ đơn với “Not only” đầu câu: “did + she + help”."},{"id":"c1-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Not only did he listen, but he also apologised.","Not only did he listened, but he also apologised.","Not only did he listening, but he also apologised."],"answer":"Not only did he listen, but he also apologised.","explanation":"Sau trợ động từ “did”, dùng động từ nguyên mẫu “listen”."},{"id":"c1-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Not only did he listen, but he also helped.","audio":"/audio/listen-c1-2-2.mp3","explanation":"Câu nghe được là: Not only did he listen, but he also helped."},{"id":"c1-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Not only did she arrive, but she also stayed.","audio":"/audio/listen-c1-2-3.mp3","explanation":"Câu nghe được là: Not only did she arrive, but she also stayed."},{"id":"reader-c1-2-r0","skill":"reading","prompt":"Who spoke first under the new arrangement?","options":["Quieter participants","The two dominant speakers","Only the facilitator"],"answer":"Quieter participants","explanation":"Người điều phối mời người ít nói phát biểu trước để thay đổi thứ tự thảo luận."},{"id":"reader-c1-2-r1","skill":"reading","prompt":"What was the facilitator’s purpose?","options":["Broaden access to influence","Accept every suggestion","End all criticism"],"answer":"Broaden access to influence","explanation":"Mục tiêu là mở cơ hội ảnh hưởng cho nhiều người, thay vì chỉ người nói tự tin."},{"id":"reader-c1-2-r2","skill":"reading","prompt":"Were all ideas practical?","options":["No","Yes","No ideas were offered"],"answer":"No","explanation":"Một số đề xuất không thực tế, dù những đề xuất khác giúp đơn giản hóa phương án."},{"id":"c1-3-g1","skill":"grammar","prompt":"It was Anna ___ solved the problem.","options":["that","what","which"],"answer":"that","explanation":"Câu chẻ nhấn mạnh người dùng “It was Anna that…”."},{"id":"c1-3-g2","skill":"grammar","prompt":"___ was her patience that impressed me.","options":["What","It","There"],"answer":"It","explanation":"Cấu trúc câu chẻ bắt đầu bằng “It was … that …”."},{"id":"c1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"It was Anna that solved it.","audio":"/audio/lesson-c1-3.mp3","explanation":"Câu mẫu là: It was Anna that solved it."},{"id":"c1-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It was Anna that solved the problem.","It was Anna what solved the problem.","It was Anna which solved the problem."],"answer":"It was Anna that solved the problem.","explanation":"Câu chẻ nhấn mạnh người dùng “It was Anna that…”."},{"id":"c1-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["What was her patience that impressed me.","It was her patience that impressed me.","There was her patience that impressed me."],"answer":"It was her patience that impressed me.","explanation":"Cấu trúc câu chẻ bắt đầu bằng “It was … that …”."},{"id":"c1-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"It was his honesty that impressed me.","audio":"/audio/listen-c1-3-2.mp3","explanation":"Câu nghe được là: It was his honesty that impressed me."},{"id":"c1-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"It was yesterday that we met.","audio":"/audio/listen-c1-3-3.mp3","explanation":"Câu nghe được là: It was yesterday that we met."},{"id":"reader-c1-3-r0","skill":"reading","prompt":"What impressed the panel most?","options":["Honesty","A flawless career","Avoiding all details"],"answer":"Honesty","explanation":"Câu chẻ nhấn mạnh sự trung thực là điều gây ấn tượng nhất."},{"id":"reader-c1-3-r1","skill":"reading","prompt":"What did the candidate explain?","options":["A mistake and later changes","Only her successes","Why all questions were unfair"],"answer":"A mistake and later changes","explanation":"Ứng viên giải thích cả sai sót và những thay đổi mình thực hiện sau đó."},{"id":"reader-c1-3-r2","skill":"reading","prompt":"What did the panel want evidence of?","options":["Judgement","Perfection in every project","A memorised speech"],"answer":"Judgement","explanation":"Hội đồng muốn bằng chứng về khả năng phán đoán, không phải một màn thể hiện hoàn hảo."},{"id":"c1-4-g1","skill":"grammar","prompt":"Having ___ the work, she went home.","options":["finish","finished","finishing"],"answer":"finished","explanation":"Sau “Having” dùng V3 “finished”; việc hoàn thành xảy ra trước việc về nhà."},{"id":"c1-4-g2","skill":"grammar","prompt":"___ checked the figures, he signed the report.","options":["Having","Have","Has"],"answer":"Having","explanation":"Cụm phân từ hoàn thành bắt đầu bằng “Having” + V3."},{"id":"c1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Having finished, she went home.","audio":"/audio/lesson-c1-4.mp3","explanation":"Câu mẫu là: Having finished, she went home."},{"id":"c1-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Having finish the work, she went home.","Having finished the work, she went home.","Having finishing the work, she went home."],"answer":"Having finished the work, she went home.","explanation":"Sau “Having” dùng V3 “finished”; việc hoàn thành xảy ra trước việc về nhà."},{"id":"c1-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Having checked the figures, he signed the report.","Have checked the figures, he signed the report.","Has checked the figures, he signed the report."],"answer":"Having checked the figures, he signed the report.","explanation":"Cụm phân từ hoàn thành bắt đầu bằng “Having” + V3."},{"id":"c1-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Having read the letter, he replied.","audio":"/audio/listen-c1-4-2.mp3","explanation":"Câu nghe được là: Having read the letter, he replied."},{"id":"c1-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Having checked the map, we left.","audio":"/audio/listen-c1-4-3.mp3","explanation":"Câu nghe được là: Having checked the map, we left."},{"id":"reader-c1-4-r0","skill":"reading","prompt":"What did the journalist do before revising?","options":["Examined original documents","Interviewed only one reader","Changed the headline randomly"],"answer":"Examined original documents","explanation":"Cụm “Having examined” đặt việc xem tài liệu gốc trước việc sửa bài."},{"id":"reader-c1-4-r1","skill":"reading","prompt":"What was wrong with the repeated figure?","options":["It referred to another year","It had no digits","It described the weather"],"answer":"It referred to another year","explanation":"Con số được nhắc nhiều lần thuộc một năm khác, nên bị dùng sai ngữ cảnh."},{"id":"reader-c1-4-r2","skill":"reading","prompt":"Why explain the correction?","options":["To repair readers’ understanding","To hide the earlier mistake","To avoid sharing evidence"],"answer":"To repair readers’ understanding","explanation":"Giải thích việc sửa giúp khôi phục hiểu biết của độc giả, không chỉ đổi một câu."},{"id":"c1-5-g1","skill":"grammar","prompt":"___ I you, I would wait.","options":["Were","Was","Am"],"answer":"Were","explanation":"Đảo ngữ giả định trang trọng dùng “Were I you”."},{"id":"c1-5-g2","skill":"grammar","prompt":"Were she here, she ___ know what to do.","options":["would","will","has"],"answer":"would","explanation":"Điều kiện giả định ở hiện tại đi với “would” ở mệnh đề kết quả."},{"id":"c1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Were I you, I would wait.","audio":"/audio/lesson-c1-5.mp3","explanation":"Câu mẫu là: Were I you, I would wait."},{"id":"c1-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Were I you, I would wait.","Was I you, I would wait.","Am I you, I would wait."],"answer":"Were I you, I would wait.","explanation":"Đảo ngữ giả định trang trọng dùng “Were I you”."},{"id":"c1-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Were she here, she would know what to do.","Were she here, she will know what to do.","Were she here, she has know what to do."],"answer":"Were she here, she would know what to do.","explanation":"Điều kiện giả định ở hiện tại đi với “would” ở mệnh đề kết quả."},{"id":"c1-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Were she here, she would understand.","audio":"/audio/listen-c1-5-2.mp3","explanation":"Câu nghe được là: Were she here, she would understand."},{"id":"c1-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Were I free, I would join you.","audio":"/audio/listen-c1-5-3.mp3","explanation":"Câu nghe được là: Were I free, I would join you."},{"id":"reader-c1-5-r0","skill":"reading","prompt":"What concerned the adviser?","options":["Unclear responsibilities","A low salary","A closed office"],"answer":"Unclear responsibilities","explanation":"Mức lương hấp dẫn nhưng trách nhiệm chỉ được mô tả chung chung, nên cần làm rõ."},{"id":"reader-c1-5-r1","skill":"reading","prompt":"What did the applicant request?","options":["A written explanation","Immediate dismissal","A new adviser"],"answer":"A written explanation","explanation":"Sau trao đổi, ứng viên yêu cầu văn bản giải thích vai trò."},{"id":"reader-c1-5-r2","skill":"reading","prompt":"Did the adviser reject the opportunity?","options":["No","Yes","He refused to discuss it"],"answer":"No","explanation":"Cố vấn không bác bỏ cơ hội; ông tách lợi ích rõ ràng khỏi câu hỏi còn bỏ ngỏ."},{"id":"c1-6-g1","skill":"grammar","prompt":"I suggest that he ___ present.","options":["be","is","being"],"answer":"be","explanation":"Thể giả định trang trọng dùng động từ nguyên mẫu “be”."},{"id":"c1-6-g2","skill":"grammar","prompt":"They suggest that she ___ the meeting.","options":["attend","attends","attended"],"answer":"attend","explanation":"Sau “suggest that” trong thể giả định, không thêm “s” vào “attend”."},{"id":"c1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I suggest that he be present.","audio":"/audio/lesson-c1-6.mp3","explanation":"Câu mẫu là: I suggest that he be present."},{"id":"c1-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I suggest that he be present.","I suggest that he is present.","I suggest that he being present."],"answer":"I suggest that he be present.","explanation":"Thể giả định trang trọng dùng động từ nguyên mẫu “be”."},{"id":"c1-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["They suggest that she attend the meeting.","They suggest that she attends the meeting.","They suggest that she attended the meeting."],"answer":"They suggest that she attend the meeting.","explanation":"Sau “suggest that” trong thể giả định, không thêm “s” vào “attend”."},{"id":"c1-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I suggest that she attend the meeting.","audio":"/audio/listen-c1-6-2.mp3","explanation":"Câu nghe được là: I suggest that she attend the meeting."},{"id":"c1-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"They recommend that he arrive early.","audio":"/audio/listen-c1-6-3.mp3","explanation":"Câu nghe được là: They recommend that he arrive early."},{"id":"reader-c1-6-r0","skill":"reading","prompt":"When should criteria be published?","options":["Before applications","After all decisions","Only if someone complains"],"answer":"Before applications","explanation":"Tiêu chí nên được công bố trước khi nhận hồ sơ, để ứng viên biết điều kiện."},{"id":"reader-c1-6-r1","skill":"reading","prompt":"What worried some members?","options":["Reduced flexibility","Too many empty rooms","A missing consultant"],"answer":"Reduced flexibility","explanation":"Một số thành viên lo công bố sớm sẽ giảm sự linh hoạt."},{"id":"reader-c1-6-r2","skill":"reading","prompt":"What was the final arrangement?","options":["Publish a framework and record exceptions","Keep everything informal","Accept every application"],"answer":"Publish a framework and record exceptions","explanation":"Ủy ban đồng ý công bố khung tiêu chí và ghi lại mọi ngoại lệ."},{"id":"c2-1-g1","skill":"grammar","prompt":"No sooner had we left ___ it rained.","options":["than","when","that"],"answer":"than","explanation":"Cặp liên từ cố định là “No sooner… than…”."},{"id":"c2-1-g2","skill":"grammar","prompt":"No sooner ___ we arrived than the lights went out.","options":["had","have","did we"],"answer":"had","explanation":"Mẫu đảo ngữ này dùng “No sooner + had + chủ ngữ + V3”."},{"id":"c2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"No sooner had we left than it rained.","audio":"/audio/lesson-c2-1.mp3","explanation":"Câu mẫu là: No sooner had we left than it rained."},{"id":"negotiation-r0","skill":"reading","prompt":"What does the chair’s hesitation suggest?","options":["The concerns may be significant","Agreement is certain","The proposal was withdrawn"],"answer":"The concerns may be significant","explanation":"Sự ngập ngừng trái với chữ “minor”, gợi rằng lo ngại đáng kể."},{"id":"negotiation-r1","skill":"reading","prompt":"What prevented the talks from collapsing?","options":["A late compromise","An early unanimous vote","A change of venue"],"answer":"A late compromise","explanation":"“But for” cho biết thỏa hiệp là điều giúp cuộc đàm phán không đổ vỡ."},{"id":"negotiation-r2","skill":"reading","prompt":"What is the purpose of the vague statement?","options":["To conceal unresolved differences","To list every objection","To reject both sides"],"answer":"To conceal unresolved differences","explanation":"Sự mơ hồ che giấu những khác biệt chưa được giải quyết."},{"id":"c2-1-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["No sooner had we left than it rained.","No sooner had we left when it rained.","No sooner had we left that it rained."],"answer":"No sooner had we left than it rained.","explanation":"Cặp liên từ cố định là “No sooner… than…”."},{"id":"c2-1-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["No sooner had we arrived than the lights went out.","No sooner have we arrived than the lights went out.","No sooner did we we arrived than the lights went out."],"answer":"No sooner had we arrived than the lights went out.","explanation":"Mẫu đảo ngữ này dùng “No sooner + had + chủ ngữ + V3”."},{"id":"c2-1-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"No sooner had I sat down than the phone rang.","audio":"/audio/listen-c2-1-2.mp3","explanation":"Câu nghe được là: No sooner had I sat down than the phone rang."},{"id":"c2-1-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"No sooner had she spoken than they agreed.","audio":"/audio/listen-c2-1-3.mp3","explanation":"Câu nghe được là: No sooner had she spoken than they agreed."},{"id":"c2-2-g1","skill":"grammar","prompt":"Hardly had we arrived ___ it rained.","options":["than","when","that"],"answer":"when","explanation":"Cặp liên từ là “Hardly… when…”, khác với “No sooner… than…”."},{"id":"c2-2-g2","skill":"grammar","prompt":"Hardly ___ she sat down when the phone rang.","options":["had","has","she had"],"answer":"had","explanation":"“Hardly” đầu câu kéo theo đảo ngữ “had she sat”."},{"id":"c2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Hardly had we arrived when it rained.","audio":"/audio/lesson-c2-2.mp3","explanation":"Câu mẫu là: Hardly had we arrived when it rained."},{"id":"c2-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Hardly had we arrived than it rained.","Hardly had we arrived when it rained.","Hardly had we arrived that it rained."],"answer":"Hardly had we arrived when it rained.","explanation":"Cặp liên từ là “Hardly… when…”, khác với “No sooner… than…”."},{"id":"c2-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Hardly had she sat down when the phone rang.","Hardly has she sat down when the phone rang.","Hardly she had she sat down when the phone rang."],"answer":"Hardly had she sat down when the phone rang.","explanation":"“Hardly” đầu câu kéo theo đảo ngữ “had she sat”."},{"id":"c2-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Hardly had the film started when he arrived.","audio":"/audio/listen-c2-2-2.mp3","explanation":"Câu nghe được là: Hardly had the film started when he arrived."},{"id":"c2-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Hardly had we left when it began to snow.","audio":"/audio/listen-c2-2-3.mp3","explanation":"Câu nghe được là: Hardly had we left when it began to snow."},{"id":"reader-c2-2-r0","skill":"reading","prompt":"What failed?","options":["The sound system","The board","The introduction’s argument"],"answer":"The sound system","explanation":"Sự cố kỹ thuật làm mất âm thanh khi người nói bắt đầu kết luận."},{"id":"reader-c2-2-r1","skill":"reading","prompt":"How did the speaker respond?","options":["Wrote the central claim","Abandoned the presentation","Repeated a long apology"],"answer":"Wrote the central claim","explanation":"Người nói dừng lại và viết luận điểm chính lên bảng."},{"id":"reader-c2-2-r2","skill":"reading","prompt":"What is the writer’s main conclusion?","options":["A thoughtful response can preserve purpose","Preparation is unnecessary","Silence always improves a speech"],"answer":"A thoughtful response can preserve purpose","explanation":"Kết luận đề cao cách ứng phó giữ mục đích thuyết trình; không phủ nhận việc chuẩn bị kỹ thuật."},{"id":"c2-3-g1","skill":"grammar","prompt":"___ your help, I would have failed.","options":["But for","Although","Even though"],"answer":"But for","explanation":"“But for your help” diễn đạt giả định nếu không có sự giúp đỡ đó."},{"id":"c2-3-g2","skill":"grammar","prompt":"But for his warning, we ___ have been lost.","options":["would","will","are"],"answer":"would","explanation":"Giả định trái với quá khứ dùng “would have + V3”."},{"id":"c2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"But for your help, I would fail.","audio":"/audio/lesson-c2-3.mp3","explanation":"Câu mẫu là: But for your help, I would fail."},{"id":"c2-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["But for your help, I would have failed.","Although your help, I would have failed.","Even though your help, I would have failed."],"answer":"But for your help, I would have failed.","explanation":"“But for your help” diễn đạt giả định nếu không có sự giúp đỡ đó."},{"id":"c2-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["But for his warning, we would have been lost.","But for his warning, we will have been lost.","But for his warning, we are have been lost."],"answer":"But for his warning, we would have been lost.","explanation":"Giả định trái với quá khứ dùng “would have + V3”."},{"id":"c2-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"But for her advice, I would have failed.","audio":"/audio/listen-c2-3-2.mp3","explanation":"Câu nghe được là: But for her advice, I would have failed."},{"id":"c2-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"But for the delay, we would have arrived earlier.","audio":"/audio/listen-c2-3-3.mp3","explanation":"Câu nghe được là: But for the delay, we would have arrived earlier."},{"id":"reader-c2-3-r0","skill":"reading","prompt":"What prevented reliance on a poor estimate?","options":["An early warning","A new advertisement","A larger office"],"answer":"An early warning","explanation":"Cảnh báo sớm của nhân viên ngăn công ty tiếp tục dùng ước tính không đáng tin."},{"id":"reader-c2-3-r1","skill":"reading","prompt":"How was the warning first received?","options":["As excessive caution","As an immediate success","As irrelevant humour"],"answer":"As excessive caution","explanation":"Ban đầu cảnh báo bị xem là quá thận trọng."},{"id":"reader-c2-3-r2","skill":"reading","prompt":"What became clearer after review?","options":["The scale of uncertainty","The need for more advertising","The employee’s holiday plans"],"answer":"The scale of uncertainty","explanation":"Sau khi rà soát các giả định, mức độ bất định mới trở nên rõ ràng."},{"id":"c2-4-g1","skill":"grammar","prompt":"___ you need help, call me.","options":["Should","Would","Had"],"answer":"Should","explanation":"“Should you need…” là cách nêu điều kiện lịch sự, trang trọng."},{"id":"c2-4-g2","skill":"grammar","prompt":"Should you ___ assistance, contact us.","options":["require","required","requires"],"answer":"require","explanation":"Sau “should”, dùng động từ nguyên mẫu “require”."},{"id":"c2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Should you need help, call me.","audio":"/audio/lesson-c2-4.mp3","explanation":"Câu mẫu là: Should you need help, call me."},{"id":"c2-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Should you need help, call me.","Would you need help, call me.","Had you need help, call me."],"answer":"Should you need help, call me.","explanation":"“Should you need…” là cách nêu điều kiện lịch sự, trang trọng."},{"id":"c2-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Should you require assistance, contact us.","Should you required assistance, contact us.","Should you requires assistance, contact us."],"answer":"Should you require assistance, contact us.","explanation":"Sau “should”, dùng động từ nguyên mẫu “require”."},{"id":"c2-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Should you require assistance, contact us.","audio":"/audio/listen-c2-4-2.mp3","explanation":"Câu nghe được là: Should you require assistance, contact us."},{"id":"c2-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Should the weather change, we will call.","audio":"/audio/listen-c2-4-3.mp3","explanation":"Câu nghe được là: Should the weather change, we will call."},{"id":"reader-c2-4-r0","skill":"reading","prompt":"When should clarification be requested?","options":["Before submitting","After rejection","Only at the final ceremony"],"answer":"Before submitting","explanation":"Lời mời yêu cầu hỏi trước khi nộp đề xuất, không phải chờ đến sau."},{"id":"reader-c2-4-r1","skill":"reading","prompt":"What did the second applicant do?","options":["Asked early and revised","Ignored all requirements","Submitted an incomplete application"],"answer":"Asked early and revised","explanation":"Ứng viên thứ hai hỏi sớm và sửa hồ sơ trước khi nộp."},{"id":"reader-c2-4-r2","skill":"reading","prompt":"What distinction matters?","options":["Politeness and procedural rules","Writing and drawing","Public and private transport"],"answer":"Politeness and procedural rules","explanation":"Giọng lịch sự không có nghĩa là bỏ các quy định thủ tục; hồ sơ thiếu vẫn không được xét lại."},{"id":"c2-5-g1","skill":"grammar","prompt":"___ I admire the plan, I cannot support it.","options":["Much as","Despite","However much of"],"answer":"Much as","explanation":"“Much as” đứng trước mệnh đề và diễn đạt sự nhượng bộ."},{"id":"c2-5-g2","skill":"grammar","prompt":"Much as I ___ her, I disagree with her decision.","options":["respect","respecting","to respect"],"answer":"respect","explanation":"Sau “Much as I” cần động từ chia trong mệnh đề, ở đây là “respect”."},{"id":"c2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Much as I admire it, I disagree.","audio":"/audio/lesson-c2-5.mp3","explanation":"Câu mẫu là: Much as I admire it, I disagree."},{"id":"c2-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Much as I admire the plan, I cannot support it.","Despite I admire the plan, I cannot support it.","However much of I admire the plan, I cannot support it."],"answer":"Much as I admire the plan, I cannot support it.","explanation":"“Much as” đứng trước mệnh đề và diễn đạt sự nhượng bộ."},{"id":"c2-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["Much as I respect her, I disagree with her decision.","Much as I respecting her, I disagree with her decision.","Much as I to respect her, I disagree with her decision."],"answer":"Much as I respect her, I disagree with her decision.","explanation":"Sau “Much as I” cần động từ chia trong mệnh đề, ở đây là “respect”."},{"id":"c2-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Much as I respect him, I disagree.","audio":"/audio/listen-c2-5-2.mp3","explanation":"Câu nghe được là: Much as I respect him, I disagree."},{"id":"c2-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Much as she enjoys travel, she prefers home.","audio":"/audio/listen-c2-5-3.mp3","explanation":"Câu nghe được là: Much as she enjoys travel, she prefers home."},{"id":"reader-c2-5-r0","skill":"reading","prompt":"What did the reviewer question?","options":["Whether complexity served the story","Whether novels should exist","Whether all experiments are bad"],"answer":"Whether complexity served the story","explanation":"Người phê bình đặt câu hỏi liệu sự phức tạp có phục vụ câu chuyện hay không."},{"id":"reader-c2-5-r1","skill":"reading","prompt":"Was the criticism against experimentation itself?","options":["No","Yes","The review never mentions experimentation"],"answer":"No","explanation":"Bà phê bình cách thực hiện, không phản đối bản thân việc thử nghiệm."},{"id":"reader-c2-5-r2","skill":"reading","prompt":"What would a simple approval/rejection label lose?","options":["The nuance of the judgement","The title of the book","The author’s age"],"answer":"The nuance of the judgement","explanation":"Nhãn chỉ khen hoặc chê làm mất sắc thái vừa ngưỡng mộ vừa chưa hài lòng."},{"id":"c2-6-g1","skill":"grammar","prompt":"From her tone, we can ___ that she disagrees.","options":["imply","infer","impose"],"answer":"infer","explanation":"Người nghe suy ra từ giọng nói dùng “infer”; “imply” là người nói hàm ý."},{"id":"c2-6-g2","skill":"grammar","prompt":"His silence may ___ disagreement.","options":["infer","imply","interpret"],"answer":"imply","explanation":"Sự im lặng gợi hàm ý nên dùng “imply”, không phải “infer”."},{"id":"c2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The speaker implies; we infer.","audio":"/audio/lesson-c2-6.mp3","explanation":"Câu mẫu là: The speaker implies; we infer."},{"id":"c2-6-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["From her tone, we can imply that she disagrees.","From her tone, we can infer that she disagrees.","From her tone, we can impose that she disagrees."],"answer":"From her tone, we can infer that she disagrees.","explanation":"Người nghe suy ra từ giọng nói dùng “infer”; “imply” là người nói hàm ý."},{"id":"c2-6-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["His silence may infer disagreement.","His silence may imply disagreement.","His silence may interpret disagreement."],"answer":"His silence may imply disagreement.","explanation":"Sự im lặng gợi hàm ý nên dùng “imply”, không phải “infer”."},{"id":"c2-6-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"We can infer the meaning from context.","audio":"/audio/listen-c2-6-2.mp3","explanation":"Câu nghe được là: We can infer the meaning from context."},{"id":"c2-6-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"Her silence may imply disagreement.","audio":"/audio/listen-c2-6-3.mp3","explanation":"Câu nghe được là: Her silence may imply disagreement."},{"id":"reader-c2-6-r0","skill":"reading","prompt":"Was approval explicitly promised?","options":["No","Yes","The proposal had already been approved"],"answer":"No","explanation":"Giám đốc chưa đưa ra cam kết phê duyệt; người quan sát tự suy ra khả năng đó."},{"id":"reader-c2-6-r1","skill":"reading","prompt":"What did the words imply?","options":["Openness to discussion","A guaranteed outcome","Immediate rejection"],"answer":"Openness to discussion","explanation":"Lời nói chỉ hàm ý sẵn sàng thảo luận, không bảo đảm kết quả."},{"id":"reader-c2-6-r2","skill":"reading","prompt":"What contributed to the misunderstanding?","options":["Listeners’ expectations","A missing proposal title","A cancelled speech"],"answer":"Listeners’ expectations","explanation":"Kỳ vọng của người nghe góp phần tạo hiểu lầm giữa điều được hứa, hàm ý và suy ra."}],"nodes":[{"id":"a0-1","order":0,"title":"Tôi là…","level":"A0","kind":"lesson","question_ids":["a0-1-g1","a0-1-g2","a0-1-d","first-day-r0","first-day-r1","first-day-r2","a0-1-g3","a0-1-g4","a0-1-d2","a0-1-d3"],"word_ids":["student","name","happy"],"legacy_ids":["a0-1-g1","a0-1-g2","a0-1-d","first-day-r0","first-day-r1","first-day-r2"]},{"id":"a0-2","order":1,"title":"Bạn là…","leve